function fmtVN(n){ const r = Math.round((+n||0)*100)/100; return String(r).replace('.', ','); }
function parseVN(v){ const x = parseFloat(String(v==null?'':v).replace(',','.')); return isNaN(x) ? null : x; }
function matrixKindTotals(){
  const t = {TN:emptyMucdoCell(),DS:emptyMucdoCell(),TLN:emptyMucdoCell(),TL:emptyMucdoCell()};
  (state.matrixRows||[]).forEach(r=> ['TN','DS','TLN','TL'].forEach(k=>{
    const c = r[k]||emptyMucdoCell();
    t[k].NB+=c.NB||0; t[k].TH+=c.TH||0; t[k].VD+=c.VD||0;
  }));
  return t;
}
/* V1.28: số câu mỗi hình thức của đề định kỳ theo số câu tự luận — giữ nguyên điểm mỗi câu, thay đổi SỐ CÂU để tổng đủ 10 điểm.
   0 tự luận: 12 TN + 4 Đ–S + 6 TLN (đúng cấu trúc đề tốt nghiệp THPT từ 2025) = 3 + 4 + 3 = 10; 1 tự luận: 12 + 3 + 6 (9 điểm, tự luận 1 điểm);
   2 – 3 tự luận: 12 + 2 + 4 (7 điểm, tự luận chia 3 điểm). Điểm mỗi câu do thầy/cô đặt khác mặc định thì tìm bộ số câu gần nhất cho đủ 10
   (tối đa theo phiếu trả lời: 18 TN, 4 câu Đ–S, 6 TLN). */
function examKindTargets(){
  const t = Math.max(0, Math.min(3, parseInt(state.soCauTuLuan) || 0)), pref = t === 0 ? {TN:12, DS:4, TLN:6} : t === 1 ? {TN:12, DS:3, TLN:6} : {TN:12, DS:2, TLN:4};
  const d = state.diemMoiCau || {}, pv = (v, dv)=>{ const x = parseVN(v); return x == null ? dv : x; };
  const dsy = pv(d.DSy, parseVN(d.DS) != null ? parseVN(d.DS)/4 : 0.25), P = {TN:pv(d.TN, 0.25), DS:4*dsy, TLN:pv(d.TLN, 0.5)}, tlFix = parseVN(d.TL);
  const sum = c=> c.TN*P.TN + c.DS*P.DS + c.TLN*P.TLN, okSum = c=>{ const s0 = sum(c); if(t === 0) return Math.abs(s0 - 10) < 1e-9; if(tlFix != null && tlFix > 0) return Math.abs(s0 + t*tlFix - 10) < 1e-9; return 10 - s0 >= 0.5*t - 1e-9; };
  if(okSum(pref)) return Object.assign({}, pref, {TL:t});
  let best = null, bd = Infinity;
  for(let a = 6; a <= 18; a++) for(let b = 0; b <= 4; b++) for(let c = 0; c <= 6; c++){ const x = {TN:a, DS:b, TLN:c}; if(!okSum(x)) continue; const dd = Math.abs(a - pref.TN)*1.2 + Math.abs(b - pref.DS)*2 + Math.abs(c - pref.TLN); if(dd < bd){ bd = dd; best = x; } }
  return Object.assign({}, best || pref, {TL:t});
}
function matrixPointScheme(){
  // Điểm mỗi câu theo hình thức; tự luận để trống thì tự chia phần điểm còn lại cho đủ 10.
  const d = state.diemMoiCau || {};
  const t = matrixKindTotals();
  const n = k=> t[k].NB+t[k].TH+t[k].VD;
  // Đúng-sai: mỗi câu 4 ý, mỗi ý có điểm riêng (mặc định 0,25đ) → điểm 1 câu = 4 × điểm mỗi ý.
  const dsy = parseVN(d.DSy) ?? (parseVN(d.DS)!=null ? parseVN(d.DS)/4 : 0.25);
  const p = {TN: parseVN(d.TN) ?? 0.25, DSy: dsy, DS: 4*dsy, TLN: parseVN(d.TLN) ?? 0.5};
  const tl = parseVN(d.TL);
  if(tl!=null && tl>0){ p.TL = tl; p.tlAuto = false; }
  else{
    const rest = 10 - (n('TN')*p.TN + n('DS')*p.DS + n('TLN')*p.TLN);
    p.TL = n('TL')>0 ? Math.max(0, rest)/n('TL') : 0; p.tlAuto = true;
  }
  p.tong = n('TN')*p.TN + n('DS')*p.DS + n('TLN')*p.TLN + n('TL')*p.TL;
  return p;
}
function buildMatrixLatex(){
  const KINDS = ['TN','DS','TLN','TL'];
  const LV = ['NB','TH','VD'];
  const KIND_LABEL = {TN:'TN nhiều lựa chọn', DS:'Đúng - sai', TLN:'Trả lời ngắn', TL:'Tự luận'};
  const targets = examKindTargets();
  const p = matrixPointScheme();
  const tongDiem = p.tong > 0 ? p.tong : 10;
  const pct = diem=> fmtVN(diem/tongDiem*100) + '\\%';
  const cellWithPoint = (n, k)=> n>0 ? `\\shortstack{${n}\\\\[-1pt]{\\scriptsize (${fmtVN(n*p[k])}đ)}}` : '0';
  const nCols = 1 + 3*KINDS.length + 1;
  let out = `% ====== Bảng ma trận đề kiểm tra — không kèm preamble, dán vào tài liệu LaTeX đã có sẵn ======
% Bảng nhiều cột nên xuất theo khổ NGANG (landscape) trên khổ A4 cho khỏi tràn trang.
% Đảm bảo preamble tài liệu đã có: \\usepackage{pdflscape}, \\usepackage{multirow}, \\usepackage{array}, \\usepackage{graphicx}  (không dùng \\usepackage{lscape} vì không xoay đúng khi xuất PDF).
% Tiêu đề + bảng + ghi chú được gói chung 1 khối: nếu cao quá 1 trang ngang thì tự thu nhỏ vừa khít 1 trang
% (không để tiêu đề bị bỏ lại 1 mình khi bảng nhảy sang trang sau); vừa rồi thì giữ nguyên cỡ.
\\begin{landscape}
\\thispagestyle{empty}
\\makeatletter\\@ifundefined{mbpMatBox}{\\newsavebox{\\mbpMatBox}}{}\\makeatother
\\renewcommand{\\arraystretch}{1.15}
\\newcolumntype{C}{>{\\centering\\arraybackslash}p{1.0cm}}
\\begin{lrbox}{\\mbpMatBox}
\\begin{minipage}{\\linewidth}
\\small\\centering
\\textbf{BẢNG MA TRẬN ĐỀ KIỂM TRA ${KYTHI_LABEL[state.kytha].toUpperCase()} — MÔN TOÁN LỚP ${state.grade}}\\par\\medskip
\\begin{tabular}{|>{\\raggedright\\arraybackslash\\footnotesize}p{\\dimexpr\\linewidth-12cm-2.1cm-28\\tabcolsep-15\\arrayrulewidth-2pt\\relax}|${KINDS.map(()=>'C|C|C').join('|')}|>{\\centering\\arraybackslash}p{2.1cm}|}
\\hline
\\multirow{2}{*}{\\textbf{Nội dung}} & ${KINDS.map(k=>`\\multicolumn{3}{c|}{\\shortstack{\\textbf{${KIND_LABEL[k]}}\\\\[-1pt]{\\scriptsize (${k==='DS' ? `${fmtVN(p.DS)}đ/câu = 4 ý × ${fmtVN(p.DSy)}đ` : `${fmtVN(p[k])}đ/câu`})}}}`).join(' & ')} & \\multirow{2}{*}{\\textbf{Tổng}} \\\\
\\cline{2-${nCols-1}}
 & ${KINDS.map(()=>LV.join(' & ')).join(' & ')} & \\\\
\\hline
`;
  (state.matrixRows||[]).forEach(r=>{
    let rowN = 0, rowD = 0;
    const cells = KINDS.map(k=>{
      const c = r[k]||emptyMucdoCell();
      return LV.map(lv=>{ const n = c[lv]||0; rowN += n; rowD += n*p[k]; return cellWithPoint(n,k); }).join(' & ');
    }).join(' & ');
    const right = rowN>0 ? `\\shortstack{${rowN} câu\\\\[-1pt]{\\scriptsize ${fmtVN(rowD)}đ -- ${pct(rowD)}}}` : '0';
    out += `${r.ten} & ${cells} & ${right} \\\\\n\\hline\n`;
  });
  const t = matrixKindTotals();
  let allN = 0, allD = 0;
  KINDS.forEach(k=> LV.forEach(lv=>{ allN += t[k][lv]; allD += t[k][lv]*p[k]; }));
  // Tổng số câu (kèm điểm) theo từng ô
  out += `\\textbf{Tổng số câu} & ${KINDS.map(k=> LV.map(lv=> cellWithPoint(t[k][lv],k)).join(' & ')).join(' & ')} & \\shortstack{\\textbf{${allN} câu}\\\\[-1pt]{\\scriptsize ${fmtVN(allD)}đ}} \\\\\n\\hline\n`;
  // Tổng theo hình thức
  out += `\\textbf{Theo hình thức} & ${KINDS.map(k=>{ const n = t[k].NB+t[k].TH+t[k].VD; return `\\multicolumn{3}{c|}{${n}/${targets[k]} câu -- ${fmtVN(n*p[k])}đ}`; }).join(' & ')} & \\textbf{${fmtVN(allD)}đ} \\\\\n\\hline\n`;
  // Dòng cuối: tỉ lệ %
  out += `\\textbf{Tỉ lệ (\\%)} & ${KINDS.map(k=> LV.map(lv=> t[k][lv]>0 ? pct(t[k][lv]*p[k]) : '0\\%').join(' & ')).join(' & ')} & \\textbf{${pct(allD)}} \\\\\n\\hline\n`;
  out += `\\end{tabular}

\\medskip
{\\footnotesize Điểm: TN nhiều lựa chọn ${fmtVN(p.TN)}đ/câu; Đúng - sai ${fmtVN(p.DS)}đ/câu (4 ý × ${fmtVN(p.DSy)}đ); Trả lời ngắn ${fmtVN(p.TLN)}đ/câu; Tự luận ${fmtVN(p.TL)}đ/câu${p.tlAuto?' (tự chia)':''}. Tổng: ${fmtVN(allD)}đ.}
\\end{minipage}
\\end{lrbox}
\\noindent\\centering
\\ifdim\\dimexpr\\ht\\mbpMatBox+\\dp\\mbpMatBox\\relax>0.96\\textheight
  \\resizebox*{!}{0.96\\textheight}{\\usebox{\\mbpMatBox}}%
\\else
  \\usebox{\\mbpMatBox}%
\\fi
\\end{landscape}
`;
  return out;
}

function buildSpecLatex(){
  // Bảng đặc tả thường dài nhiều trang → dùng longtable: tự ngắt trang, lặp dòng tiêu đề cột ở đầu mỗi trang.
  const KIND_LABEL = {TN:'TN nhiều lựa chọn', DS:'Đúng - sai', TLN:'Trả lời ngắn', TL:'Tự luận'};
  let out = `% ====== Bảng đặc tả đề kiểm tra — không kèm preamble, dán vào tài liệu LaTeX đã có sẵn ======
% Đảm bảo preamble tài liệu đã có: \\usepackage{longtable} và \\usepackage{array}
`;
  out += `\\begin{center}\n\\textbf{BẢNG ĐẶC TẢ ĐỀ KIỂM TRA ${KYTHI_LABEL[state.kytha].toUpperCase()} — MÔN TOÁN LỚP ${state.grade}}\n\\end{center}\n`;
  const head = `\\textbf{Nội dung} & \\textbf{Mức độ} & \\textbf{Số câu} & \\textbf{Mô tả yêu cầu cần đạt} \\\\\n\\hline\n`;
  ['TN','DS','TLN','TL'].forEach(kind=>{
    const list = state.specs.filter(s=>s.hinhthuc===kind);
    if(!list.length) return;
    const tong = list.reduce((t,s)=> t + (parseInt(s.soCau)||0), 0);
    out += `{\\renewcommand{\\arraystretch}{1.2}
\\begin{longtable}{|>{\\raggedright\\arraybackslash}p{4.5cm}|>{\\centering\\arraybackslash}p{1.9cm}|>{\\centering\\arraybackslash}p{1.1cm}|>{\\raggedright\\arraybackslash}p{7.6cm}|}
\\multicolumn{4}{l}{\\textbf{${KIND_LABEL[kind]}}} \\\\[2pt]
\\hline
${head}\\endfirsthead
\\multicolumn{4}{l}{\\small\\textit{${KIND_LABEL[kind]} (tiếp theo)}} \\\\[2pt]
\\hline
${head}\\endhead
\\hline
\\multicolumn{4}{r}{\\small\\textit{(còn tiếp)}} \\\\
\\endfoot
\\endlastfoot
`;
    list.forEach(s=>{
      const mota = (s.moTa||'').replace(/\n/g,' ');
      out += `${s.ten} & ${MUCDO_LABEL[s.mucdo]||s.mucdo} & ${s.soCau} & ${mota} \\\\\n\\hline\n`;
    });
    out += `\\multicolumn{2}{|r|}{\\textbf{Tổng}} & \\textbf{${tong}} & \\\\\n\\hline\n\\end{longtable}}\n\\vspace{6pt}\n\n`;
  });
  return out;
}

function readFileAsDataURL(file){
  return new Promise((resolve,reject)=>{
    const reader = new FileReader();
    reader.onload = e=> resolve(e.target.result);
    reader.onerror = ()=> reject(new Error('Lỗi đọc file ảnh'));
    reader.readAsDataURL(file);
  });
}

function existingBankSamplesText(kind, rows, maxPerRow, maxTotal){
  maxPerRow = maxPerRow || 3; maxTotal = maxTotal || 15;
  let lines = [];
  rows.forEach(r=>{
    const samples = state.bank
      .filter(b=> b.hinhthuc===kind && b.noidung===r.ten && b.data)
      .slice(0, maxPerRow)
      .map(b=>{
        const text = kind==='DS' ? b.data.dannhap : b.data.cauhoi;
        return text ? String(text).replace(/\s+/g,' ').slice(0,140) : null;
      })
      .filter(Boolean);
    samples.forEach(s=> lines.push(`- (${r.ten}) ${s}`));
  });
  return lines.slice(0, maxTotal);
}

function bankPriorityOrder(){
  // Thứ tự loại câu (chỉ các loại đang bật) — dùng khi lấy câu từ kho để sinh đề.
  return ['1'];      // V1.57: chỉ còn câu thay số / câu cố định
}
function moveBankPriority(i, dir){
  const o = (Array.isArray(state.bankPriority) && state.bankPriority.length===3 ? state.bankPriority : ['1','2','3']).map(String);
  const j = i + dir; if(j<0 || j>=o.length) return;
  [o[i], o[j]] = [o[j], o[i]]; state.bankPriority = o; saveLocal(); renderStep3();
}
function toggleBankLoai(l, on){ if(!state.bankUseLoai) state.bankUseLoai = {1:true,2:true,3:true}; state.bankUseLoai[l] = !!on; saveLocal(); renderStep3(); }
function bankAvailByLoai(){
  // số câu dùng được trong kho theo loại (lớp đang soạn, chưa dùng cho đề hiện tại)
  const c = {'1':0,'2':0,'3':0};
  state.bank.forEach(b=>{ if(bankUsable(b) && !state.usedBankIds.includes(b.id) && (!b.grade || String(b.grade)===String(state.grade))) c[String(b.loai||3)] = (c[String(b.loai||3)]||0)+1; });
  return c;
}
function genTypeCoverage(){
  // Câu thay số: mỗi dạng chỉ góp 1 câu/mã đề → đếm số DẠNG có sẵn trong từng ô ma trận và so với số câu cần
  const cell = new Map(), all = new Set();
  state.bank.forEach(b=>{ const k = b.data && b.data._gen && b.data._gen.key; if(!k || String(b.loai||3)!=='1') return;
    if(!bankUsable(b) || !bankForThpt(b) || state.usedBankIds.includes(b.id) || (b.grade && String(b.grade)!==String(state.grade))) return;
    all.add(k); const id = b.hinhthuc + '|' + b.noidung + '|' + b.mucdo; if(!cell.has(id)) cell.set(id, new Map()); cell.get(id).set(k, (cell.get(id).get(k)||0) + 1); });
  try{ Object.keys(GENLIB.GEN).forEach(k=>{ const g = GENLIB.GEN[k]; if(String(g.grade) !== String(state.grade) || !genForExam(k)) return; all.add(k); const id = (g.kind||'TN') + '|' + GENLIB.genNoidung(g) + '|' + g.mucdo; if(!cell.has(id)) cell.set(id, new Map()); cell.get(id).set(k, Math.max(g.fixed ? 1 : 2, cell.get(id).get(k)||0)); }); }catch(e){}   // V1.25: dạng thay số đã xác nhận luôn dùng được, không cần có câu trong kho
  let need = 0, got = 0, got2 = 0; const lack = [], cells = [];
  (state.matrixRows||[]).forEach(r=> ['TN','DS','TLN','TL'].forEach(kind=> ['NB','TH','VD'].forEach(md=>{ const n = (r[kind] && r[kind][md]) || 0; if(n <= 0) return;
    const mp = cell.get(kind + '|' + r.ten + '|' + md) || new Map(), h = mp.size, h2 = [...mp.values()].reduce((t,c)=> t + Math.min(2,c), 0); need += n; got += Math.min(n, h); got2 += Math.min(n, h2); if(h < n){ lack.push(`${r.ten} · ${kind} · ${md}: cần ${n}, có ${h} dạng`); cells.push({ten:r.ten, kind, md, need:n, dang:h, cau:h2, keys:[...mp.keys()]}); } })));
  return {types: all.size, need, got, got2, lack, cells};
}
function showCoverageDetail(){
  // Bảng chi tiết các ô ma trận chưa đủ dạng thay số: dạng nào đã có, dạng nào có trong phần mềm nhưng chưa sinh vào kho / chưa xác nhận.
  const cov = genTypeCoverage();
  const MD = {NB:'Nhận biết', TH:'Thông hiểu', VD:'Vận dụng'}, KN = {TN:'TN ABCD', DS:'Đúng/Sai', TLN:'Trả lời ngắn', TL:'Tự luận'};
  const GEN = (typeof GENLIB!=='undefined' && GENLIB.GEN) || {};
  const rows = cov.cells.map(c=>{
    const short = c.cau < c.need;
    const cand = Object.keys(GEN).filter(k=>{ const g = GEN[k]; return String(g.grade)===String(state.grade) && genIsThpt(k) && (g.kind||'TN')===c.kind && g.mucdo===c.md && GENLIB.genNoidung(g)===c.ten; });
    const items = cand.map(k=>{
      const g = GEN[k], inBank = genBankCount(k), tested = genTestedInfo(k), used = c.keys.includes(k);
      const st = used ? `<span class="badge ok">dùng được — sinh câu khi tạo đề</span>`
        : !tested ? `<span class="badge warn">chưa xác nhận kiểm thử</span>`
        : g.fixed && !fixedOn(k) ? `<span class="badge warn">câu cố định — đang bỏ tích</span>`
        : `<span class="badge warn">chưa dùng được</span>`;
      return `<li style="margin:3px 0">${escHtml(g.dang)} — ${st}</li>`;
    }).join('');
    return `<tr style="${short?'background:#fff4ec':''}"><td style="text-align:left">${escHtml(c.ten)}</td><td>${KN[c.kind]}</td><td>${MD[c.md]}</td><td>${c.need}</td><td><b style="color:${short?'#b3261e':'#1b7a3a'}">${c.cau}</b> câu / ${c.dang} dạng</td>
      <td style="text-align:left">${items ? `<ul style="margin:0;padding-left:18px">${items}</ul>` : '<span class="small-text">Phần mềm chưa có dạng thay số nào cho ô này</span>'}</td></tr>`;
  }).join('');
  const nShort = cov.cells.filter(c=> c.cau < c.need).length;
  showAppModal(`<h3 style="margin:0 0 6px">Độ phủ câu thay số theo ma trận</h3>
    <p class="small-text" style="margin:0 0 10px">Mỗi dạng góp tối đa 2 câu (khác số) cho một mã đề. Dòng tô cam là ô <b>còn thiếu câu</b> (${nShort} ô) — phần thiếu sẽ lấy từ câu LaTeX / câu đã duyệt trong kho; vẫn thiếu thì nhật ký báo để bổ sung. Các dòng còn lại đủ câu nhưng phải dùng 2 câu cùng dạng.</p>
    ${rows ? `<div style="overflow:auto"><table class="students" style="width:100%;font-size:14px"><tr><th>Nội dung</th><th>Hình thức</th><th>Mức độ</th><th>Cần</th><th>Đang có</th><th>Dạng thay số trong phần mềm</th></tr>${rows}</table></div>` : '<p>Mọi ô đều đủ dạng.</p>'}`);
}
function covAddGen(k){
  const n = genAddToBank(k, 5, true);
  saveLocal();
  log(`Sinh ${n} câu thay số vào kho — ${GENLIB.genNoidung(GENLIB.GEN[k])}.`);
  renderAll(); showCoverageDetail();
}
function bankPriorityHtml(){
  const cov = genTypeCoverage();
  const covHtml = cov.need===0 ? '' : cov.got >= cov.need ? `<br><span class="badge ok" title="Mỗi ô của ma trận đều có đủ số dạng thay số khác nhau — không cần loại khác hay AI">✓ Đủ dạng (${cov.need}/${cov.need} câu)</span>`
    : cov.got2 >= cov.need ? `<br><span class="badge ok" style="cursor:pointer" onclick="showCoverageDetail()" title="Bấm để xem các ô phải dùng 2 câu cùng dạng">✓ Đủ câu, ${cov.need - cov.got} câu lặp dạng (khác số)</span>`
    : `<br><span class="badge warn" style="cursor:pointer" onclick="showCoverageDetail()" title="Bấm để xem ô nào còn thiếu">Đủ ${cov.got2}/${cov.need} câu — thiếu ${cov.need - cov.got2} <b style="text-decoration:underline">· xem</b></span>`;
  return `<div class="card">
    <label style="margin:0">Nguồn câu hỏi khi sinh đề</label>
    <p class="small-text" style="margin:4px 0 8px">Mỗi ô của ma trận (nội dung × hình thức × mức độ) lấy câu từ các dạng <b>Câu hỏi thay số</b> và <b>Câu hỏi cố định</b> đã duyệt: mỗi dạng 1 câu trong một mã đề; thiếu dạng thì cho tối đa 2 câu cùng dạng, khác số.</p>
    <p style="margin:0 0 6px">Lớp ${state.grade}: <b>${cov.types} dạng</b> đã duyệt${covHtml}</p>
    <label class="inl" style="margin-top:10px;display:flex" title="Mã đề gốc 1 chọn dạng câu tự luận; các mã đề gốc sau dùng ĐÚNG các dạng đó, cùng thứ tự, chỉ thay số — số ý hỏi và độ khó tương đương giữa các mã đề"><input type="checkbox" ${state.tlSameForm===false ? '' : 'checked'} onchange="state.tlSameForm=this.checked; saveLocal(); renderStep3();"> ✍️ <b>Tự luận: các mã đề gốc cùng dạng, chỉ thay số</b> <span class="small-text">(theo mã đề gốc 1 — số ý hỏi tương đương)</span></label>
    <div class="flexrow" style="margin-top:10px;align-items:center;gap:8px">
      <span>🖼 Tỉ lệ câu <b>có hình</b> (đồ thị, bảng biến thiên, hình vẽ) nhắm tới mỗi phần:</span>
      <input type="number" min="0" max="100" step="5" style="width:80px" value="${Math.round(figRatio()*100)}" onchange="state.figRatio=Math.max(0,Math.min(100,parseFloat(this.value)||0)); saveLocal(); renderStep3();"> %
      
    </div>
    <p class="small-text" style="margin:6px 0 0">App ưu tiên các dạng có hình cho đủ tỉ lệ này. Cùng điều kiện, câu có <b>lượt dùng ít hơn</b> được lấy trước.</p>
  </div>`;
}
function bankFigAvail(){
  return state.bank.filter(b=> bankUsable(b) && !state.usedBankIds.includes(b.id) && (!b.grade || String(b.grade)===String(state.grade)) && hasFigure(b.data)).length;
}
function hasFigure(q){
  // Câu "có hình": đồ thị / bảng biến thiên / hình TikZ (trường hinhVe) hoặc hình chèn thẳng trong đề bài
  if(!q) return false;
  const h = q.hinhVe;
  if(h && (typeof h==='object' || String(h).trim())) return true;
  return /\\begin\{tikzpicture\}|\\includegraphics|\\begin\{tikzonimage\}/.test(String(q.cauhoi||'')+String(q.dannhap||''));
}
function figRatio(){ const v = parseFloat(state.figRatio); return isFinite(v) ? Math.max(0, Math.min(100, v))/100 : 0.2; }
function figTargetFor(total){ return Math.round(total*figRatio()); }
function bankUseAdd(id, d){
  const b = (state.bank||[]).find(x=> x.id===id);
  if(b) b.luotDung = Math.max(0, (b.luotDung||0) + d);
}
/* V13.7: câu có ĐỒ THỊ / BẢNG BIẾN THIÊN của hàm bậc bốn chỉ thuộc nhóm ĐGNL — không dùng cho đề giữa kỳ, cuối kỳ (THPT).
   Dạng thay số thuộc THPT khi không mang nhãn ĐGNL, hoặc mang cả nhãn THPT (dạng có tham số m vẫn dùng cho đề định kỳ). */
const _quarticMemo = new Map();
function polyDegreeOf(expr){
  // bậc của hàm đa thức (0..8) theo sai phân hữu hạn; không phải đa thức → -1
  const key = String(expr||''); if(_quarticMemo.has(key)) return _quarticMemo.get(key);
  let deg = -1;
  try{
    const f = mathCompile(mathParse(key));
    const ys = []; for(let i=0;i<12;i++) ys.push(f(-2.7 + i*0.53));
    if(ys.every(v=> typeof v==='number' && isFinite(v))){
      let d = ys.slice(), sc = Math.max(1, ...ys.map(Math.abs));
      for(let k=0;k<=9;k++){ if(d.every(v=> Math.abs(v) < 1e-7*sc)){ deg = k-1; break; } d = d.slice(1).map((v,i)=> v - d[i]); }
    }
  }catch(e){}
  _quarticMemo.set(key, deg); return deg;
}
function figIsQuartic(hv){
  if(!hv || typeof hv!=='object') return false;
  if((hv.loai==='dothi' || hv.loai==='bbt') && hv.hamSo && polyDegreeOf(hv.hamSo)===4) return true;
  if(hv.loai==='bbt' && !hv.hamSo && Array.isArray(hv.x) && hv.x.length===5 && /infty/.test(hv.x[0]) && /infty/.test(hv.x[4])){
    // bảng dạng chữ W / M: hai đầu cùng một vô cực, ba điểm cực trị
    const y = hv.y||[]; return /infty/.test(String(y[0])) && String(y[0]).replace(/\s/g,'')===String(y[4]).replace(/\s/g,'');
  }
  return false;
}
/* V1.22: dạng NGOÀI chương trình GDPT 2018 (chỉ hợp ôn ĐGNL) — không lấy khi sinh đề giữa kỳ, cuối kỳ (lớp 10–12):
   câu có tham số m, a sin x + b cos x, hàm bậc bốn (trùng phương). Thầy/cô muốn dùng lại dạng nào thì sửa nhãn dạng đó thành THPT ở mục Câu hỏi thay số. */
const _genOut18 = new Map();
function genOut18(k){
  if(_genOut18.has(k)) return _genOut18.get(k);
  const g = GENLIB.GEN[k]; let w = '';
  if(g && g.out18) w = g.out18;
  else if(g && g.grade >= 10){ const d = String(g.dang||''), V = 'a-zA-Zà-ỹÀ-ỸđĐ';
    if(/trùng phương|bậc bốn|bậc 4\b/i.test(d)) w = 'hàm số bậc bốn (trùng phương)';
    else if(/a\s*sin\s*x\s*[+−-]\s*b\s*cos\s*x|sin\s*x\s*[+−-]\s*cos\s*x\s*=\s*m|bậc nhất (đối )?với sin/i.test(d)) w = 'biểu thức, phương trình dạng a sin x + b cos x';
    else { const d2 = d.replace(/phương trình tham số( và phương trình chính tắc)?/gi, '');
      if(/tham số/i.test(d2) || new RegExp(`(tìm|đếm|nguyên|của|giá trị|tập giá trị của)\\s+(số\\s+)?(giá trị\\s+)?(nguyên\\s+)?m(?![${V}])`, 'i').test(d2)) w = 'câu có tham số m';
      else { try{ const b = GENLIB.genBuild(g, 777), t = b ? String(b.q.cauhoi || b.q.dannhap || '') : ''; if(/(giá trị|tham số)[^.]{0,30}\$m\$/.test(t)) w = 'câu có tham số m'; }catch(e){} } } }
  _genOut18.set(k, w); return w; }
function genIsThpt(k){ const t = genTagsOf(k), own = state.genTags && Array.isArray(state.genTags[k]) && state.genTags[k].includes('THPT');
  if(t.includes('ĐGNL') && !t.includes('THPT')) return false;
  return own || !genOut18(k); }
function bankForThpt(b){
  // câu trong kho có được dùng cho đề giữa kỳ / cuối kỳ không
  const k = b && b.data && b.data._gen && b.data._gen.key;
  if(k && GENLIB.GEN[k] && !genIsThpt(k)) return false;
  return !figIsQuartic(b && b.data && b.data.hinhVe);
}
function pullFromBank(kind, rows, figTarget, usedGen){
  // Lấy câu đã duyệt trong kho cho từng ô ma trận (nội dung × hình thức × mức độ), chưa dùng cho đề đang soạn.
  //  1) Ưu tiên đủ khoảng figTarget câu CÓ HÌNH (đồ thị, bảng biến thiên…) — rải đều các ô;
  //  2) phần còn lại: theo thứ tự ưu tiên loại câu; cùng loại thì ưu tiên câu KHÔNG hình (để tỉ lệ hình không vượt quá nhiều),
  //  3) cùng điều kiện thì câu có LƯỢT DÙNG ít hơn trước, hoà nhau thì chọn ngẫu nhiên.
  const reused = [];
  const remainingRows = rows.map(r=>({...r, [kind]: {...r[kind]}}));
  const pri = bankPriorityOrder();
  const rnd = new Map(); const tie = b=>{ if(!rnd.has(b.id)) rnd.set(b.id, Math.random()); return rnd.get(b.id); };
  const pr = b=> pri.indexOf(String(b.loai||3));
  const taken = new Set(state.usedBankIds||[]);
  // V1.12: dạng câu (cả họ dạng) đã dùng nhiều ở các đề trước thì xếp sau — đề mới đổi dạng, không chỉ đổi số
  const famUse = new Map(); (state.bank||[]).forEach(b=>{ const k = b && b.data && b.data._gen && b.data._gen.key, f = k && ((GENLIB.GEN[k]||{}).fam || k); if(f && b.luotDung) famUse.set(f, (famUse.get(f)||0) + b.luotDung); });
  const fu = b=>{ const k = b.data && b.data._gen && b.data._gen.key, f = k && ((GENLIB.GEN[k]||{}).fam || k); return f ? (famUse.get(f)||0) : 0; };
  // Mỗi DẠNG câu thay số chỉ góp tối đa 1 câu trong một mã đề gốc (tính cả các phần khác của mã đề đó)
  //  → nếu sau khi lấy hết các loại mà ô vẫn thiếu thì cho phép thêm câu thứ 2 cùng dạng (khác số); không bao giờ quá 2.
  const genSeen = usedGen instanceof Map ? usedGen : new Map([...(usedGen||[])].map(k=> [k,1])), gk = b=>{ const k = (b.data && b.data._gen && b.data._gen.key) || null; return k && ((GENLIB.GEN[k]||{}).fam || k); };
  const cands = (r, md, cap)=> state.bank.filter(b=> b.hinhthuc===kind && b.noidung===r.ten && b.mucdo===md && !taken.has(b.id) && !(gk(b) && (genSeen.get(gk(b))||0) >= (cap||1)) && bankUsable(b) && bankForThpt(b) && pri.includes(String(b.loai||3)));
  const take = (cell, b)=>{
    reused.push({...b.data, _fromBank:true, _status:'approved', _bankId:b.id, _nguoiDuyet:b.nguoiDuyet, _loai:b.loai||3});
    state.usedBankIds.push(b.id); taken.add(b.id); bankUseAdd(b.id, +1); if(gk(b)) genSeen.set(gk(b), (genSeen.get(gk(b))||0) + 1);
    cell.r[kind][cell.md]--;
  };
  const cells = [];
  remainingRows.forEach(r=> ['NB','TH','VD'].forEach(md=>{ if((r[kind][md]||0)>0) cells.push({r, md}); }));
  let figs = 0;
  const target = Math.max(0, figTarget==null ? figTargetFor(cells.reduce((s,c)=> s+c.r[kind][c.md], 0)) : figTarget);
  // Lượt 1: câu có hình — mỗi vòng, mỗi ô (thứ tự ngẫu nhiên) lấy tối đa 1 câu
  const order = shuffleArray(cells.slice());
  let progress = true;
  while(figs < target && progress){
    progress = false;
    for(const c of order){
      if(figs >= target) break;
      if(c.r[kind][c.md] <= 0) continue;
      const f = cands(c.r, c.md).filter(b=> hasFigure(b.data))
        .sort((x,y)=> pr(x)-pr(y) || fu(x)-fu(y) || (x.luotDung||0)-(y.luotDung||0) || tie(x)-tie(y))[0];
      if(f){ take(c, f); figs++; progress = true; }
    }
  }
  // Lượt 2: lấp phần còn lại
  cells.forEach(c=>{
    while(c.r[kind][c.md] > 0){
      const avoidFig = figs >= target;
      const srt = (x,y)=> pr(x)-pr(y)
          || (avoidFig ? (hasFigure(x.data)?1:0)-(hasFigure(y.data)?1:0) : 0)
          || fu(x)-fu(y) || (x.luotDung||0)-(y.luotDung||0) || tie(x)-tie(y);
      const b = cands(c.r, c.md, 1).sort(srt)[0] || cands(c.r, c.md, 2).sort(srt)[0];
      if(!b) break;
      take(c, b); if(hasFigure(b.data)) figs++;
    }
  });
  // Lượt 3 (chỉ phần tự luận): kho thiếu câu tự luận thì dùng câu TRẢ LỜI NGẮN cùng ô (giữ đề, lời giải; thêm dòng đáp số)
  if(kind==='TL') cells.forEach(c=>{
    while(c.r.TL[c.md] > 0){
      const pool = cap=> state.bank.filter(b=> b.hinhthuc==='TLN' && b.noidung===c.r.ten && b.mucdo===c.md && !taken.has(b.id) && !(gk(b) && (genSeen.get(gk(b))||0) >= cap) && bankUsable(b) && bankForThpt(b) && pri.includes(String(b.loai||3)));
      const srt = (x,y)=> pr(x)-pr(y) || (x.luotDung||0)-(y.luotDung||0) || tie(x)-tie(y);
      const b = pool(1).sort(srt)[0] || pool(2).sort(srt)[0]; if(!b) break;
      const d = {...b.data, _fromBank:true, _status:'approved', _bankId:b.id, _nguoiDuyet:b.nguoiDuyet, _loai:b.loai||3, _tuTLN:true}, da = String(d.dapan||'').trim(); delete d.dapan;
      if(da && !/Đáp số/.test(String(d.loigiai||''))) d.loigiai = (d.loigiai ? String(d.loigiai).replace(/\s*$/, '') + '<br>' : '') + 'Đáp số: $' + da + '$.';
      reused.push(d); state.usedBankIds.push(b.id); taken.add(b.id); bankUseAdd(b.id, +1); if(gk(b)) genSeen.set(gk(b), (genSeen.get(gk(b))||0) + 1);
      c.r.TL[c.md]--;
    }
  });
  return {reused, remainingRows: remainingRows.filter(r=> rowTotal(r,kind)>0), figs, target};
}
/* ---------- QUY TẮC CÂU TRẮC NGHIỆM ABCD ----------
   - Đúng 1 phương án đúng; 4 phương án khác nhau (kể cả khác nhau về GIÁ TRỊ: ½ và 0,5 là trùng)
   - KHÔNG có phương án tham chiếu phương án khác: "Cả A và B đều đúng", "Tất cả các phương án trên", "Cả ba đều đúng", "Không có đáp án nào đúng"… */
const TN_RULES_PROMPT = `QUY TẮC BẮT BUỘC cho câu trắc nghiệm 4 phương án A, B, C, D:
- Mỗi câu có ĐÚNG MỘT phương án đúng; ba phương án còn lại đều sai rõ ràng (phương án nhiễu lấy từ sai lầm thường gặp của học sinh).
- Bốn phương án phải KHÁC NHAU, kể cả khác nhau về giá trị (không được có hai phương án bằng nhau như $\\dfrac{1}{2}$ và $0{,}5$, hay $2$ và $\\sqrt{4}$).
- TUYỆT ĐỐI KHÔNG dùng phương án tham chiếu đến phương án khác hoặc gộp phương án, ví dụ: "Cả A và B đều đúng", "A và C đúng", "Cả ba phương án trên đều đúng", "Tất cả các đáp án trên", "Không có phương án nào đúng". Mỗi phương án phải là một đáp số / một khẳng định độc lập.
- Nếu muốn hỏi nhiều khẳng định cùng lúc, hãy hỏi dạng "Có bao nhiêu khẳng định đúng?" với các phương án là các số.`;
const TN_REF_RE = /(tất\s+cả\s+(các\s+)?(phương án|đáp án|câu|ý|khẳng định)|các\s+(phương án|đáp án)\s+(trên|còn lại|đã cho)|(phương án|đáp án)\s+(trên|còn lại)|cả\s+(hai|ba|bốn|2|3|4)\s+(phương án|đáp án|câu|ý|khẳng định)|không\s+có\s+(phương án|đáp án|câu|ý|khẳng định)\s+nào|(^|[\s,(])cả\s+[A-D]\s*(,|và)|\b[A-D]\s*(và|,)\s*[A-D]\s+(đều\s+)?(đúng|sai)|(^|[\s,(])cả\s[^.]{0,40}đều\s+(đúng|sai)|\((I|II|III|IV)\)\s*(và|,)\s*\((I|II|III|IV)\))/i;
function tnOptNorm(t){
  return String(t==null?'':t).replace(/\\left|\\right|\\,|\;|\\!|\\displaystyle/g,'').replace(/\{,\}/g, ',').replace(/\$/g,'')
    .replace(/\\[dt]frac/g,'\\frac').replace(/\s+/g,'').replace(/[.;]+$/,'').toLowerCase();
}
function tnOptValue(t){
  const s = String(t==null?'':t).replace(/\{,\}/g, ',').replace(/\$/g,'').trim();
  if(!/\d/.test(s) || /[a-zA-Z]{2,}/.test(s.replace(/\\(d|t)?frac|\\sqrt|\\pi|\\infty/g,''))) return NaN;
  const v = parseTexNum(s);
  return isFinite(v) ? v : NaN;
}
function tnOptionIssues(q){
  // Trả về danh sách lỗi của 4 phương án (rỗng = hợp lệ)
  const L = ['A','B','C','D'], issues = [];
  const ref = L.filter(l=> TN_REF_RE.test(String(q[l]||'').replace(/\$[^$]*\$/g,' ')));
  if(ref.length) issues.push(`phương án ${ref.join(', ')} tham chiếu/gộp phương án khác ("cả … đều đúng", "tất cả các phương án trên"…) — không được dùng`);
  const dups = [];
  for(let i=0;i<4;i++) for(let j=i+1;j<4;j++){
    const a = q[L[i]], b = q[L[j]];
    if(!String(a||'').trim() || !String(b||'').trim()) continue;
    const va = tnOptValue(a), vb = tnOptValue(b);
    if(tnOptNorm(a)===tnOptNorm(b) || (!isNaN(va) && !isNaN(vb) && Math.abs(va-vb) < 1e-9*Math.max(1,Math.abs(va)))) dups.push(L[i]+' và '+L[j]);
  }
  if(dups.length) issues.push(`hai phương án trùng nhau (${dups.join('; ')})`);
  return issues;
}
function qInvalid(kind, q){
  // Luôn kiểm lại theo bộ kiểm tra hiện hành — cờ cũ có thể đã lưu từ phiên bản trước.
  try{ q._invalid = !validateQuestion(kind, q); }catch(e){}
  return !!q._invalid;
}
const _validMemo = new WeakMap();   // V21.6: nhớ kết quả kiểm tra đủ trường theo nội dung câu (đẩy kho 40.000 câu trước đây mất vài giây)
function validateQuestion(kind, q){
  if(!q || typeof q!=='object') return missingFields(kind, q || {}).length === 0;
  const sig = questionRawSig(kind, q) + '\u0002' + (q.dapan==null ? '' : q.dapan) + '\u0002' + (Array.isArray(q.menhde) ? q.menhde.map(m=> m && typeof m.dung==='boolean' ? (m.dung ? 1 : 0) : '?').join('') : '');
  const m = _validMemo.get(q); if(m && m.sig===sig) return m.val;
  const val = missingFields(kind, q).length === 0; _validMemo.set(q, {sig, val}); return val;
}
function missingFields(kind, q){
  const missing = [];
  if(kind==='TN'){
    if(!q.cauhoi) missing.push('nội dung câu hỏi');
    ['A','B','C','D'].forEach(l=>{ if(!q[l]) missing.push('phương án '+l); });
    if(!q.dapan || !['A','B','C','D'].includes(q.dapan)) missing.push('đáp án đúng');
    tnOptionIssues(q).forEach(s=> missing.push(s));
  } else if(kind==='DS'){
    if(!q.dannhap) missing.push('đoạn dẫn');
    const m = q.menhde;
    if(!Array.isArray(m) || m.length!==4){
      missing.push('đủ 4 mệnh đề');
    }else{
      m.forEach((mm,i)=>{
        const lb = ['a','b','c','d'][i];
        if(!mm || !mm.text) missing.push('nội dung mệnh đề '+lb);
        if(!mm || typeof mm.dung!=='boolean') missing.push('đúng/sai mệnh đề '+lb);
      });
    }
  } else if(kind==='TLN'){
    if(!q.cauhoi) missing.push('nội dung câu hỏi');
    if(!q.dapan) missing.push('đáp án');
  } else if(kind==='TL'){
    if(!q.cauhoi) missing.push('nội dung câu hỏi');
  }
  if(q.hinhVe && q.hinhVe.loai==='dothi' && !q.hinhVe.gk){   // gk: đồ thị đường gãy khúc dựng sẵn từ bảng điểm (bộ sinh đã kiểm) — bỏ kiểm tra đồ thị tốn thời gian
    const v = graphValidate(q.hinhVe);
    if(v.errors.length) missing.push('đồ thị vẽ được ('+v.errors[0]+')');
  }
  if(q.hinhVe && q.hinhVe.loai==='mien'){
    const v = mienValidate(q.hinhVe);
    if(v.errors.length) missing.push('miền nghiệm vẽ được ('+v.errors[0]+')');
  }
  if(q.hinhVe && q.hinhVe.loai==='bbt'){
    const v = bbtValidate(q.hinhVe);
    if(v.errors.length) missing.push('bảng biến thiên đúng ('+v.errors[0]+(v.errors.length>1?` và ${v.errors.length-1} lỗi khác`:'')+')');
  }
  return missing;
}
function tagQuestions(list, rootIdx, kind){
  list.forEach((q,i)=>{
    if(!q._id) q._id = `${rootIdx}-${kind}-${Date.now()}-${i}-${Math.random().toString(36).slice(2,6)}`;
    autoReview(kind, q);
  });
  return list;
}
/* V1.58: PHẦN MỀM TỰ DUYỆT — không còn tài khoản, không duyệt thủ công.
   Câu đầy đủ, không lỗi thì tự duyệt; câu thiếu dữ liệu ở trạng thái chờ cho đến khi sửa xong (sửa xong tự duyệt lại).
   Câu giáo viên bấm "Từ chối" giữ nguyên trạng thái từ chối. */
const AUTO_DUYET = 'Tự động';
function autoReview(kind, q){
  if(!q || q._status === 'rejected') return q;
  q._invalid = !validateQuestion(kind, q);
  if(q._invalid){ q._status = 'pending'; q._nguoiDuyet = ''; }
  else if(q._status !== 'approved'){ q._status = 'approved'; q._nguoiDuyet = AUTO_DUYET; }
  return q;
}
function autoReviewAll(){
  (state.roots||[]).forEach(r=>{ if(r) ['TN','DS','TLN','TL'].forEach(k=> (r[k]||[]).forEach(q=> autoReview(k, q))); });
  const im = state.imported; if(im) ['TN','DS','TLN','TL'].forEach(k=> (im[k]||[]).forEach(q=> autoReview(k, q)));
}
function repairMenhdeLabels(q){
  // Đảm bảo mỗi mệnh đề đúng-sai luôn có nhãn a/b/c/d — phòng dữ liệu cũ/nguồn khác thiếu nhãn (hiện "undefined)").
  if(q && Array.isArray(q.menhde)){
    const labels = ['a','b','c','d'];
    q.menhde = q.menhde.map((mm,i)=> mm ? {...mm, label: labels[i]} : {label:labels[i], text:'', dung:false});
  }
  return q;
}
function repairAllMenhdeLabels(){
  let count = 0;
  function fix(q){
    if(!q || !Array.isArray(q.menhde)) return;
    const before = JSON.stringify(q.menhde.map(mm=>mm&&mm.label));
    repairMenhdeLabels(q);
    const after = JSON.stringify(q.menhde.map(mm=>mm&&mm.label));
    if(before!==after) count++;
  }
  state.bank.forEach(b=>{ if(b.hinhthuc==='DS' && b.data) fix(b.data); });
  state.roots.forEach(r=>{ if(r && r.DS) r.DS.forEach(fix); });
  if(state.imported && state.imported.DS) state.imported.DS.forEach(fix);
  if(count>0){
    log(`Đã tự sửa nhãn a)/b)/c)/d) bị thiếu cho ${count} câu đúng-sai trong dữ liệu hiện có.`);

  }
  return count;
}
function formatShortAnswerVN(raw){
  // Chuẩn hoá đáp án trả lời ngắn theo đúng chuẩn phiếu THPT: tối đa 4 ký tự,
  // gồm cả dấu '-' (nếu âm) và dấu ',' (nếu có phần thập phân) — tự làm tròn khi cần cho vừa.
  let s = String(raw==null?'':raw).trim().replace(',', '.');
  const num = parseFloat(s);
  if(isNaN(num)) return String(raw||'').replace(/\s+/g,'').slice(0,4);
  const neg = num < 0;
  const abs = Math.abs(num);
  const budget = neg ? 3 : 4; // số ký tự dành cho phần số, không tính dấu '-'
  let dec = 3, str = '';
  while(dec>=0){
    str = abs.toFixed(dec).replace(/0+$/,'').replace(/\.$/,'');
    if(str.length<=budget) break;
    dec--;
  }
  if(str.length>budget){
    str = Math.round(abs).toString().slice(0,budget);
  }
  return (neg?'-':'') + str.replace('.', ',');
}
function normalizeTNAnswerToA(q){
  // Đưa nội dung đáp án đúng về vị trí A trong đề gốc (chưa trộn) để duyệt cho nhanh —
  // vị trí thật sự chỉ được xáo ngẫu nhiên khi trộn mã đề ở bước 6.
  if(!q || !['A','B','C','D'].includes(q.dapan) || q.dapan==='A') return q;
  const correctText = q[q.dapan];
  q[q.dapan] = q.A;
  q.A = correctText;
  q.dapan = 'A';
  return q;
}
const BBT_PROMPT = String.raw`Riêng BẢNG BIẾN THIÊN: KHÔNG viết mã TikZ hay tkz-tab. Cho trường "hinhVe" là object thông số dưới đây, phần mềm sẽ tự vẽ bảng chính xác:
{"loai":"bbt","nhan":["x","y'","y"],"x":["-\\infty","-1","3","+\\infty"],"dau":["+","-","+"],"tai":["","0","0",""],"y":["-\\infty","6","-26","+\\infty"],"hamSo":"x^3-3x^2-9x+1"}
- "x": các mốc theo thứ tự tăng dần (LaTeX, không có dấu $).
- "dau": dấu của y' trên từng khoảng giữa hai mốc liên tiếp (số phần tử = số mốc − 1), chỉ gồm "+" hoặc "-".
- "tai": y' tại từng mốc: "0" nếu y' = 0; "||" nếu hàm số không xác định tại mốc đó (vạch kép); "" nếu không ghi (hai đầu ±∞).
- "y": giá trị (hoặc giới hạn) của y tại từng mốc; tại mốc "||" ghi giới hạn trái và phải cách nhau bởi dấu "|", ví dụ "-\\infty | +\\infty".
- "hamSo": công thức hàm số dùng để lập bảng, viết dạng x^3-3x^2+1 hoặc (2x+1)/(x-1), để phần mềm đối chiếu từng giá trị — luôn ghi, kể cả khi đề chỉ cho bảng mà không cho công thức.
Riêng ĐỒ THỊ HÀM SỐ: KHÔNG vẽ bằng TikZ. Cho "hinhVe" là {"loai":"dothi","hamSo":"x^3-3x+1"} — phần mềm tự vẽ đồ thị, tự căn khung hình, tự vẽ tiệm cận và ghi toạ độ các điểm cực trị. Có thể thêm "ten":"(C)" để ghi tên đồ thị, "diem":[1,2] để đánh dấu thêm các điểm có hoành độ đó. "hamSo" viết dạng x^2-4x+3, (2x+1)/(x-1), 2^x, (1/2)^x, log_2(x), ln(x), sqrt(x+1).
Riêng MIỀN NGHIỆM của bất phương trình / hệ bất phương trình bậc nhất hai ẩn: KHÔNG vẽ bằng TikZ. Cho "hinhVe" là {"loai":"mien","bpt":[{"a":2,"b":3,"c":6,"dau":"<="}]} (mỗi phần tử là a·x + b·y (dau) c, dau là "<", ">", "<=", ">=") — phần mềm tự vẽ, GẠCH SỌC phần KHÔNG thuộc miền nghiệm, bờ nét liền nếu kể cả bờ, nét đứt nếu không kể bờ; đề bài phải nói rõ "phần không bị gạch" là miền nghiệm.`;
function normalizeOneHinhVe(hv){
  // Chuẩn hoá trường hình vẽ: chuỗi TikZ, object bảng biến thiên (thông số), ảnh.
  // Mã tkz-tab (bảng biến thiên AI tự viết) được đọc lại thành thông số để app tự vẽ lại chính xác.
  if(hv==null) return undefined;
  if(typeof hv==='string'){
    const ma = hv.trim();
    if(!ma) return undefined;
    if(/\\tkzTabInit/.test(ma)){ const b = parseTkzTab(ma); if(b) return b; }
    return {loai:'tikz', ma};
  }
  if(typeof hv!=='object') return undefined;
  if(hv.loai==='bbt' || (!hv.loai && Array.isArray(hv.x) && (hv.dau||hv.y))) return bbtNormalize(hv);
  if(hv.loai==='dothi' || (!hv.loai && hv.hamSo)) return graphNormalize(hv);
  if(hv.loai==='mien' || (!hv.loai && Array.isArray(hv.bpt))) return mienNormalize(hv);
  if(hv.loai==='luoi') return luoiNormalize(hv);
  if(hv.loai==='hinh' || (!hv.loai && hv.dang)) return hinhNormalize(hv);
  if(hv.loai==='tikz' && hv.ma && /\\tkzTabInit/.test(hv.ma)){ const b = parseTkzTab(hv.ma); if(b) return b; }
  if(!hv.loai) return undefined; // dạng không hợp lệ, bỏ qua an toàn
  return hv;
}
function migrateBbtAll(){
  // Chuyển các bảng biến thiên đang lưu dạng mã tkz-tab (kho, đề gốc, câu bổ sung) sang thông số. Trả về số câu đã chuyển.
  let n = 0;
  const fix = q=>{
    if(q && q.hinhVe && q.hinhVe.loai==='tikz' && /\\tkzTabInit/.test(q.hinhVe.ma||'')){ const b = parseTkzTab(q.hinhVe.ma); if(b){ q.hinhVe = b; n++; } }
    // hình miền nghiệm nay gạch sọc (không tô màu) → sửa lời dẫn cũ cho khớp hình
    if(q && q.hinhVe && q.hinhVe.loai==='mien') ['cauhoi','dannhap','loigiai'].forEach(f=>{ if(typeof q[f]==='string') q[f] = q[f].replace(/không bị tô màu|không bị tô đậm/g, 'không bị gạch').replace(/phần không bị tô(?= )/g, 'phần không bị gạch'); });
  };
  (state.bank||[]).forEach(b=> fix(b.data));
  (state.roots||[]).forEach(r=> r && ['TN','DS','TLN','TL'].forEach(k=> (r[k]||[]).forEach(fix)));
  if(state.imported) ['TN','DS','TLN','TL'].forEach(k=> (state.imported[k]||[]).forEach(fix));
  (state.variants||[]).forEach(v=> ['TN','DS','TLN','TL'].forEach(k=> (v[k]||[]).forEach(fix)));
  return n;
}
/* V1.13: TỰ LUẬN CÙNG DẠNG GIỮA CÁC MÃ ĐỀ GỐC — mã đề gốc sau lấy đúng dạng câu tự luận của mã đề gốc đầu (cùng thứ tự), sinh lại với số khác.
   Lấy cùng mức độ từ kho thì có khi một mã 1 ý, mã khác 3 ý → điểm và độ khó không tương đương; thay số giữ nguyên cấu trúc câu. */
function tlSameFormPart(rootIdx){
  if(state.tlSameForm === false) return null;
  const ids = rootIndexes(), ref = ids.find(i=> i < rootIdx && ((state.roots[i]||{}).TL||[]).length);
  if(ref == null) return null;
  const refQs = state.roots[ref].TL, out = [], left = [], seen = new Set(refQs.map(q=> computeQuestionHashes('TL', q).hash));
  refQs.forEach(rq=>{
    const g = rq._gen && GENLIB.GEN[rq._gen.key], gk = g && (g.kind || 'TN');
    if(!g || (gk !== 'TL' && gk !== 'TLN')){ left.push(rq); return; }
    let q = null;
    for(let t = 0; t < 30 && !q; t++){ const seed = Math.floor(Math.random()*1e9), b = GENLIB.genBuild(g, seed); if(!b) continue;
      let d = {...b.q, noidung:rq.noidung, mucdo:rq.mucdo, _status:genTestedInfo(g.key) ? 'approved' : 'pending', _nguon:'Thay số (lõi)', _gen:{key:g.key, seed, v:GENLIB.GEN_VERSION, fix:GEN_FIXES[g.key]||0}, _thaySo:ref + 1};
      if(gk === 'TLN'){ const da = String(d.dapan||'').trim(); delete d.dapan; d._tuTLN = true; if(da && !/Đáp số/.test(String(d.loigiai||''))) d.loigiai = (d.loigiai ? String(d.loigiai).replace(/\s*$/, '') + '<br>' : '') + 'Đáp số: $' + da + '$.'; }
      const h = computeQuestionHashes('TL', d).hash; if(seen.has(h)) continue; seen.add(h); q = d; }
    if(q) out.push(q); else left.push(rq); });
  return {ref, out, left};
}
async function generatePart(rootIdx, kind){
  if(kind === 'TL'){ const S = tlSameFormPart(rootIdx);
    if(S && !S.left.length){
      if(!state.roots[rootIdx]) state.roots[rootIdx] = {TN:[],DS:[],TLN:[],TL:[]};
      const prevIds = new Set((state.roots[rootIdx].TL||[]).filter(q=> q._fromBank && q._bankId).map(q=> q._bankId));
      if(prevIds.size){ state.usedBankIds = (state.usedBankIds||[]).filter(id=> !prevIds.has(id)); prevIds.forEach(id=> bankUseAdd(id, -1)); }
      state.roots[rootIdx].TL = tagQuestions(S.out, rootIdx, 'TL');
      log(`✓ Phần TL mã đề gốc ${rootIdx+1}: cùng ${S.out.length} dạng câu tự luận với mã đề gốc ${S.ref+1}, chỉ thay số (số ý hỏi tương đương).`);
      renderStep3(); return; }
    if(S && S.left.length) log(`ℹ Phần TL mã đề gốc ${rootIdx+1}: ${S.left.length} câu tự luận của mã đề gốc ${S.ref+1} không phải câu thay số nên không sinh lại số được — lấy như thường lệ.`);
  }
  // Sinh lại phần này: trả lại các câu kho mà lần sinh trước đã lấy (để có thể dùng lại)
  const prevPart = (state.roots[rootIdx] && state.roots[rootIdx][kind]) || [];
  const prevIds = new Set(prevPart.filter(q=> q._fromBank && q._bankId).map(q=> q._bankId));
  if(prevIds.size){ state.usedBankIds = (state.usedBankIds||[]).filter(id=> !prevIds.has(id)); prevIds.forEach(id=> bankUseAdd(id, -1)); }
  const rows = state.matrixRows.filter(r=> rowTotal(r,kind) > 0);
  const tongCauGoc = rows.reduce((s,r)=> s+rowTotal(r,kind), 0);
  if(tongCauGoc===0){ alert('Chưa gán số câu nào cho phần này trong ma trận (bước 2).'); return; }
  const figTarget = figTargetFor(tongCauGoc);
  const {reused, remainingRows, figs: figFromBank} = pullFromBank(kind, rows, figTarget, (()=>{ const u = new Map(), root = state.roots[rootIdx] || {};
    ['TN','DS','TLN','TL'].forEach(k=>{ if(k!==kind) (root[k]||[]).forEach(q=>{ if(q && q._gen && q._gen.key) u.set(q._gen.key, (u.get(q._gen.key)||0) + 1); }); }); return u; })());
  const figNeed = Math.max(0, figTarget - figFromBank);
  if(reused.length){
    const byL = {}; reused.forEach(q=>{ const l = q._loai||3; byL[l] = (byL[l]||0)+1; });
    log(`Lấy ${reused.length} câu từ kho đã duyệt cho phần ${kind} (mã đề gốc ${rootIdx+1}): ${Object.keys(byL).map(l=>`${BANK_LOAI[l]} ${byL[l]} câu`).join(', ')}.`);
  }
  const generated = [];
  const remainingCau = remainingRows.reduce((s,r)=>s+rowTotal(r,kind),0);
  if(remainingCau>0){
    const thieu = remainingRows.map(r=> `${r.ten} (${rowTotal(r,kind)} câu)`).join('; ');
    log(`⚠ Phần ${kind} (mã đề gốc ${rootIdx+1}) còn thiếu ${remainingCau} câu: ${thieu}. Bổ sung bằng cách viết thêm dạng thay số / câu cố định, hoặc nạp câu LaTeX vào kho, rồi bấm Sinh lại phần này.`);
  }
  if(!state.roots[rootIdx]) state.roots[rootIdx] = {TN:[],DS:[],TLN:[],TL:[]};
  state.roots[rootIdx][kind] = tagQuestions([...reused, ...generated], rootIdx, kind);
  const invalidCount = state.roots[rootIdx][kind].filter(q=>qInvalid(kind,q)).length;
  const figAll = state.roots[rootIdx][kind].filter(hasFigure).length;
  log(`✓ Phần ${kind} mã đề gốc ${rootIdx+1}: ${reused.length} câu — ${figAll}/${state.roots[rootIdx][kind].length} câu có hình (mục tiêu ~${figTarget}).`);
  if(invalidCount>0){
    log(`⚠ ${invalidCount} câu phần ${kind} thiếu dữ liệu (thiếu đáp án/nội dung) — vào nút Duyệt câu hỏi trong mục Tạo đề gốc để xem và sửa.`);
  }
  renderStep3();
}

function reviewPendingCount(){
  let pending = 0, rejected = 0, total = 0;
  rootIndexes().forEach(i=>{ const r = state.roots[i] || {}; ['TN','DS','TLN','TL'].forEach(k=> (r[k]||[]).forEach(q=>{ total++; if(q._status==='rejected') rejected++; else if(q._status!=='approved') pending++; })); });
  (state.imported ? ['TN','DS','TLN','TL'] : []).forEach(k=> ((state.imported||{})[k]||[]).forEach(q=>{ if(q && q._status==='pending') pending++; }));
  return {pending, rejected, total};
}
/* Tạo đề: lập bộ đề MỚI cho kỳ thi — bỏ các mã đề gốc đang có (câu kho đã dùng vẫn tính lượt dùng nên được ưu tiên thấp hơn), rồi tạo lại toàn bộ */
async function createNewExam(){
  const has = rootIndexes().some(i=> rootHasQuestions(state.roots[i]));
  if(has && !confirm('Tạo bộ đề MỚI cho kỳ thi?\n\nCác mã đề gốc đang có và các mã đề đã trộn sẽ bị thay bằng bộ mới. Câu chưa duyệt trong bộ cũ sẽ mất (câu đã duyệt vẫn nằm trong kho).')) return;
  const fresh = ()=>{ try{ examSaveCurrent(true); }catch(e){} rootIndexes().forEach(i=>{ state.roots[i] = {TN:[],DS:[],TLN:[],TL:[]}; }); state.variants = []; state.usedBankIds = []; };
  const n = rootIndexes().length;
  fresh();
  await generateAllRoots_run();
  { const st = reviewPendingCount(); log(`Đã tạo bộ đề mới.${st.pending ? ` Còn ${st.pending} câu chưa duyệt — bấm "Duyệt câu hỏi".` : ''}`); }
  saveLocal(); if(state.step===4) renderStep3();
}
async function generateAllRoots(){ return generateAllRoots_run(); }
/* V1.25: CÂU THAY SỐ KHÔNG CẦN KHO — khi sinh đề gốc, mỗi dạng thay số đã xác nhận (khớp ô ma trận, dùng được cho đề định kỳ)
   được sinh ngay 2 câu mới để chọn; câu nào được chọn mới lưu lại (để nhớ lượt dùng, đổi dạng ở đề sau), câu không dùng bỏ đi.
   Kho vẫn dùng cho câu LaTeX (loại 2) và câu AI đã duyệt (loại 3). */
// V1.35: câu cố định (không thay số) có dùng khi ra đề hay không — tích chung ở bước Ma trận + bỏ tích từng câu
function fixedOn(k){ const g = GENLIB.GEN[k]; return !g || !g.fixed || (state.useFixed !== false && !(state.fixedOff||{})[k]); }
function genForExam(k){ return genTestedInfo(k) && genIsThpt(k) && fixedOn(k); }
const _pullFromBankKho = pullFromBank;
pullFromBank = function(kind, rows, figTarget, usedGen){
  const n0 = state.bank.length, cells = new Set(); (rows||[]).forEach(r=> ['NB','TH','VD'].forEach(md=>{ if(((r[kind]||{})[md]||0) > 0) cells.add(r.ten + '|' + md); }));
  if(cells.size && typeof GENLIB !== 'undefined'){ const hs = new Set();
    try{ Object.keys(GENLIB.GEN).forEach(k=>{ const g = GENLIB.GEN[k]; if(String(g.grade) !== String(state.grade) || (g.kind||'TN') !== kind || !cells.has(GENLIB.genNoidung(g) + '|' + g.mucdo) || !genForExam(k)) return; genAddToBank(k, g.fixed ? 1 : 2, true, true, hs); }); }catch(e){ console.warn(e); } }
  const added = state.bank.slice(n0); added.forEach(b=>{ b._auto = true; });
  let out; try{ out = _pullFromBankKho(kind, rows, figTarget, usedGen); }
  finally{ if(added.length){ const used = new Set(state.usedBankIds||[]), drop = new Set(added.filter(b=> !used.has(b.id)).map(b=> b.id)); if(drop.size) state.bank = state.bank.filter(b=> !drop.has(b.id)); _genCnt = null; } }
  return out; };
async function generateAllRoots_run(){
  for(const r of rootIndexes()){
    for(const kind of ['TN','DS','TLN','TL']){
      if(!state.matrixRows.some(row=> rowTotal(row,kind) > 0)) continue;   // phần không có câu trong ma trận → bỏ qua, không báo lỗi
      await generatePart(r, kind);
    }
  }
  log(`Hoàn tất sinh ${rootIndexes().length} mã đề gốc.`);
}

/* ============================================================
   5. TRỘN MÃ ĐỀ
   ============================================================ */
const NO_SHUFFLE_RE = /(tất cả|cả hai|cả ba|cả bốn|các phương án|các đáp án|phương án (trên|A|B|C|D)|đáp án (trên|A|B|C|D)|đều đúng|đều sai|không có (phương án|đáp án)|\b[A-D] và [A-D]\b)/i;
function tnKeepOrder(q){ return ['A','B','C','D'].some(l=> NO_SHUFFLE_RE.test(String(q[l]||''))); }
function shuffleTNQuestion(q){
  // Phương án kiểu "Cả A và B đều đúng", "Tất cả các phương án trên" → giữ nguyên thứ tự để không sai nghĩa
  if(tnKeepOrder(q)) return {...q};
  const opts = [{l:'A',t:q.A},{l:'B',t:q.B},{l:'C',t:q.C},{l:'D',t:q.D}];
  const correctText = (opts.find(o=>o.l===q.dapan)||{}).t;
  const texts = shuffleArray(opts.map(o=>o.t));
  const labels = ['A','B','C','D'];
  const nq = {...q};
  labels.forEach((l,i)=> nq[l]=texts[i]);
  const idx = texts.indexOf(correctText);
  nq.dapan = labels[idx>=0?idx:0];
  return nq;
}
function shuffleDSQuestion(q){
  const props = shuffleArray(q.menhde||[]);
  const labels=['a','b','c','d'];
  const nq = {...q};
  nq.menhde = props.map((p,i)=>({label:labels[i], text:p.text, dung:p.dung}));
  return nq;
}
/* V1.15: mỗi mã đề THAY SỐ các câu thay số (cùng dạng, cùng mức độ, số liệu và đáp án khác) — hai mã đề bất kì, kể cả cùng mã đề gốc,
   không giống nhau hoàn toàn; câu không phải thay số (AI, LaTeX) vẫn giữ nguyên nội dung, chỉ đảo thứ tự câu và phương án. */
function variantReroll(q, kind){
  if(state.mixThaySo === false || !q || !q._gen || typeof GENLIB === 'undefined') return q;
  const g = GENLIB.GEN[q._gen.key]; if(!g) return q; const gk = g.kind || 'TN';
  if(!(gk === kind || (kind === 'TL' && gk === 'TLN'))) return q;
  const h0 = computeQuestionHashes(kind, q).hash;
  for(let t = 0; t < 12; t++){ const seed = Math.floor(Math.random()*1e9), b = GENLIB.genBuild(g, seed); if(!b || (b.raw && b.raw.verify && b.raw.verify() !== true)) continue;
    const d = {...b.q, noidung:q.noidung, mucdo:q.mucdo, _status:q._status, _id:q._id, _nguon:q._nguon || 'Thay số (lõi)', _gen:{key:g.key, seed, v:GENLIB.GEN_VERSION, fix:(typeof GEN_FIXES !== 'undefined' && GEN_FIXES[g.key]) || 0}, _thaySoTron:true};
    if(kind === 'TL' && gk === 'TLN'){ const da = String(d.dapan||'').trim(); delete d.dapan; d._tuTLN = true; if(da && !/Đáp số/.test(String(d.loigiai||''))) d.loigiai = (d.loigiai ? String(d.loigiai).replace(/\s*$/, '') + '<br>' : '') + 'Đáp số: $' + da + '$.'; }
    if(computeQuestionHashes(kind, d).hash !== h0) return d; }
  return q;
}
function buildVariant(root, code, rootId){
  return {
    code, rootId,
    TN: shuffleArray(root.TN||[]).map(q=> shuffleTNQuestion(variantReroll(q, 'TN'))),
    DS: shuffleArray(root.DS||[]).map(q=> shuffleDSQuestion(variantReroll(q, 'DS'))),
    TLN: shuffleArray(root.TLN||[]).map(q=> variantReroll(q, 'TLN')),
    TL: shuffleArray(root.TL||[]).map(q=> variantReroll(q, 'TL'))
  };
}
function countStatusFor(bucket){
  let pending=0, rejected=0, approved=0, total=0;
  if(bucket){
    ['TN','DS','TLN','TL'].forEach(k=>{
      (bucket[k]||[]).forEach(q=>{
        total++;
        if(q._status==='approved') approved++;
        else if(q._status==='rejected') rejected++;
        else pending++;
      });
    });
  }
  return {pending, rejected, approved, total};
}
function rootIndexes(){
  const n = Math.max(1, Math.min(4, parseInt(state.numRoots)||4));
  return Array.from({length:n}, (_,i)=>i);
}
function setNumRoots(n){
  state.numRoots = Math.max(1, Math.min(4, parseInt(n)||4));
  if(activeRoot >= state.numRoots) activeRoot = 0;
  if(typeof reviewSource==='number' && reviewSource >= state.numRoots) reviewSource = 0;
  saveLocal();
  renderAll();
}
function countReviewStatus(){
  let pending=0, rejected=0, approved=0, total=0;
  rootIndexes().map(i=>state.roots[i]).forEach(root=>{
    if(!root) return;
    ['TN','DS','TLN','TL'].forEach(k=>{
      (root[k]||[]).forEach(q=>{
        total++;
        if(q._status==='approved') approved++;
        else if(q._status==='rejected') rejected++;
        else pending++;
      });
    });
  });
  return {pending, rejected, approved, total};
}
function rootHasQuestions(r){
  return !!r && ['TN','DS','TLN','TL'].some(k=> Array.isArray(r[k]) && r[k].length>0);
}
/* V1.73: CHỐNG CHÉP BÀI giữa MỌI cặp mã đề — giáo viên không biết ai ngồi cạnh ai, nên hai mã bất kì cũng phải lệch đáp án nhau.
   Học sinh chép thường chép VỊ TRÍ Ô TÔ, nên tối ưu đáp án theo vị trí câu:
   - Trắc nghiệm: mỗi vị trí câu, chữ cái đáp án chia đều A/B/C/D giữa các mã, rồi đổi chỗ để không cặp mã nào trùng nhiều bất thường (cực tiểu tổng bình phương số câu trùng).
   - Đúng – sai: chọn thứ tự 4 ý của từng mã để bảng Đ/S ở mỗi vị trí câu khác nhau nhiều nhất giữa mọi cặp.
   - Trả lời ngắn: ở mỗi vị trí câu, đáp số các mã khác nhau (thay số lại khi trùng).
   Chép của bạn bất kì cũng chỉ đúng ngang đoán mò. */
function antiCopyOptimize(V){ const n = V.length; if(n < 2) return null; const rnd = Math.random, L = ['A','B','C','D'], pairs = n*(n - 1)/2;
  // --- Trắc nghiệm
  const nT = Math.min(...V.map(v=> (v.TN||[]).length)); let tnAvg = 0, tnMax = 0;
  if(nT){ const M = V.map(v=> v.TN.slice(0, nT).map(q=> Math.max(0, L.indexOf(q.dapan)))), fx = V.map(v=> v.TN.slice(0, nT).map(q=> tnKeepOrder(q)));
    for(let p = 0; p < nT; p++){ const cnt = [0, 0, 0, 0], free = []; for(let v = 0; v < n; v++){ if(fx[v][p]) cnt[M[v][p]]++; else free.push(v); }
      const seq = free.map(()=>{ let b = 0; for(let c = 1; c < 4; c++) if(cnt[c] < cnt[b] || (cnt[c] === cnt[b] && rnd() < 0.5)) b = c; cnt[b]++; return b; });
      shuffleArray(seq).forEach((x, i)=> M[free[i]][p] = x); }
    const S = Array.from({length:n}, ()=> new Array(n).fill(0)); for(let a = 0; a < n; a++) for(let b = a + 1; b < n; b++){ let m = 0; for(let p = 0; p < nT; p++) if(M[a][p] === M[b][p]) m++; S[a][b] = S[b][a] = m; }
    const F = Array.from({length:nT + 2}, (_, m)=> Math.pow(4, m));   // phạt rất nặng cặp trùng nhiều câu → kéo cặp trùng nhiều nhất xuống
    for(let it = 0; it < 80000; it++){ const p = Math.floor(rnd()*nT), v1 = Math.floor(rnd()*n), v2 = Math.floor(rnd()*n), x = M[v1][p], y = M[v2][p]; if(v1 === v2 || x === y || fx[v1][p] || fx[v2][p]) continue;
      let d = 0; for(let w = 0; w < n; w++){ if(w === v1 || w === v2) continue; const c = M[w][p], d1 = (c === y) - (c === x); if(d1){ d += F[S[v1][w] + d1] - F[S[v1][w]] + F[S[v2][w] - d1] - F[S[v2][w]]; } }
      if(d < 0 || (d === 0 && rnd() < 0.3)){ M[v1][p] = y; M[v2][p] = x; for(let w = 0; w < n; w++){ if(w === v1 || w === v2) continue; const c = M[w][p], d1 = (c === y) - (c === x); if(d1){ S[v1][w] += d1; S[w][v1] += d1; S[v2][w] -= d1; S[w][v2] -= d1; } } } }
    for(let v = 0; v < n; v++) for(let p = 0; p < nT; p++){ if(fx[v][p]) continue; const q = V[v].TN[p], ok = q[q.dapan], others = shuffleArray(L.filter(l=> l !== q.dapan).map(l=> q[l])), nq = {...q}; let k = 0;
      L.forEach((l, i)=>{ nq[l] = i === M[v][p] ? ok : others[k++]; }); nq.dapan = L[M[v][p]]; V[v].TN[p] = nq; }
    let sum = 0; for(let a = 0; a < n; a++) for(let b = a + 1; b < n; b++){ sum += S[a][b]; tnMax = Math.max(tnMax, S[a][b]); } tnAvg = sum/pairs/nT; }
  // --- Đúng – sai
  const nD = Math.min(...V.map(v=> (v.DS||[]).length)); let dsSame = 0;
  if(nD){ const PERM = []; (function g(a, r){ if(!r.length){ PERM.push(a); return; } r.forEach((x, i)=> g(a.concat(x), r.filter((_, j)=> j !== i))); })([], [0, 1, 2, 3]);
    const pat = q=> (q.menhde||[]).map(m=> m.dung ? 1 : 0), cur = V.map(v=> v.DS.slice(0, nD).map(pat));
    for(let pass = 0; pass < 3; pass++) for(const v of shuffleArray([...Array(n).keys()])) for(let p = 0; p < nD; p++){ const base = V[v].DS[p]; if((base.menhde||[]).length !== 4) continue;
      let best = null, bc = Infinity; for(const pm of shuffleArray(PERM.slice())){ const pt = pm.map(i=> base.menhde[i].dung ? 1 : 0); let c = 0; for(let w = 0; w < n; w++){ if(w === v) continue; const o = cur[w][p]; let m = 0; for(let j = 0; j < 4; j++) if(pt[j] === o[j]) m++; c += m*m; } if(c < bc){ bc = c; best = pm; } }
      const nq = {...base, menhde:best.map((i, j)=> ({...base.menhde[i], label:'abcd'[j]}))}; V[v].DS[p] = nq; cur[v][p] = pat(nq); }
    for(let a = 0; a < n; a++) for(let b = a + 1; b < n; b++) for(let p = 0; p < nD; p++) if(cur[a][p].join('') === cur[b][p].join('')) dsSame++; dsSame = dsSame/pairs/nD; }
  // --- Trả lời ngắn: đáp số khác nhau ở mỗi vị trí câu
  const nL = Math.min(...V.map(v=> (v.TLN||[]).length)); let tlDup = 0; const norm = x=> String(x == null ? '' : x).replace(/\s|\$/g, '').replace('.', ',');
  for(let p = 0; p < nL; p++){ const seen = new Set(); for(let v = 0; v < n; v++){ let q = V[v].TLN[p];
      for(let t = 0; t < 15 && seen.has(norm(q.dapan)) && q._gen; t++){ const r = variantReroll(q, 'TLN'); if(r !== q && !seen.has(norm(r.dapan))){ q = r; break; } }
      V[v].TLN[p] = q; if(seen.has(norm(q.dapan))) tlDup++; seen.add(norm(q.dapan)); } }
  return {n, nT, tnAvg, tnMax, nD, dsSame, nL, tlDup}; }
function generateVariants(total){
  // Chỉ tính mã đề gốc thực sự có câu hỏi (ô trống do mở tab ở bước Duyệt không tính) — 1 mã đề gốc vẫn trộn được.
  const filledRoots = rootIndexes().map(i=> rootHasQuestions(state.roots[i]) ? {r:state.roots[i],i} : null).filter(Boolean);
  if(filledRoots.length===0){ alert('Chưa có mã đề gốc nào có câu hỏi (bước 4 — Tạo đề gốc).'); return; }
  total = Math.max(1, Math.min(99, parseInt(total)||1));
  const stat = countReviewStatus();
  if(stat.total===0){ alert('Chưa có câu hỏi nào để trộn.'); return; }
  if(stat.pending>0 || stat.rejected>0){
    alert(`Đề chưa được duyệt hết nên chưa thể trộn mã đề để xuất:\n- Còn ${stat.pending} câu đang chờ duyệt\n- Còn ${stat.rejected} câu đã bị từ chối (cần sửa lại rồi duyệt, hoặc sinh câu thay thế)\ntrong tổng số ${stat.total} câu.\nVào bước "Duyệt câu hỏi" xử lý hết rồi quay lại đây.`);
    return;
  }
  if(state.variants && state.variants.length){
    const graded = (state.students||[]).some(s=> studentHasAnswers(s));
    const msg = `Đã có ${state.variants.length} mã đề trộn trước đó. Trộn lại sẽ THAY TOÀN BỘ nội dung và đáp án của các mã đề (kể cả khi trùng số mã đề).\n` +
      (graded ? '⚠ Đã có bài làm của học sinh được chấm theo các mã đề cũ — trộn lại sẽ làm sai kết quả chấm.\n' : '') +
      'Nếu đề cũ đã in/phát cho học sinh thì KHÔNG nên trộn lại. Vẫn trộn lại?';
    if(!confirm(msg)) return;
  }
  const perRoot = Math.floor(total/filledRoots.length);
  const extra = total % filledRoots.length;
  let variants = [];
  if(!(state.startCode>=1000)) state.startCode = 1001;
  if(state.startCode + total - 1 > 9999) state.startCode = Math.max(1000, 9999 - total + 1);
  let code = state.startCode;
  // V1.15: xếp mã đề XEN KẼ các mã đề gốc (1001 gốc A, 1002 gốc B, 1003 gốc C…, thứ tự gốc ngẫu nhiên) — gán theo danh sách lớp thì hai em liền nhau khác mã đề gốc
  const ord = shuffleArray(filledRoots.slice()), cnt = ord.map((x, idx)=> perRoot + (idx < extra ? 1 : 0));
  for(let k = 0; variants.length < total; k++){ const idx = k % ord.length; if(cnt[idx] <= 0) continue; cnt[idx]--; variants.push(buildVariant(ord[idx].r, code, ord[idx].i + 1)); code++; }
  if((state.students||[]).length){ state.students.forEach((st, i)=> st.made = variants[i % variants.length].code); let nb = 0; try{ nb = sbdAssign(state.students); }catch(e){}   // V1.76: lớp đã chọn → tự gán mỗi em một mã đề
    log(`Đã gán mã đề cho ${state.students.length} học sinh${variants.length < state.students.length ? ` (vòng lặp ${variants.length} mã)` : ' — mỗi em một mã'}${nb ? `, cấp mới ${nb} số báo danh` : ''}.`); }
  state.examAk = wakNextId();   // V1.74: mỗi lần trộn là một kỳ thi mới → mã bài mới (không bao giờ trùng)
  state.variants = variants; const ac = state.antiCopy === false ? null : antiCopyOptimize(variants); state.lastAntiCopy = ac;
  const nRe = variants.reduce((t, v)=> t + ['TN','DS','TLN','TL'].reduce((u, k)=> u + (v[k]||[]).filter(q=> q && q._thaySoTron).length, 0), 0), nAll = variants.reduce((t, v)=> t + ['TN','DS','TLN','TL'].reduce((u, k)=> u + (v[k]||[]).length, 0), 0);
  try{ examSaveCurrent(true); }catch(e){}
  if(ac) log(`Chống chép bài (so mọi cặp trong ${ac.n} mã đề):${ac.nT ? ` trắc nghiệm trùng đáp án trung bình ${Math.round(ac.tnAvg*100)}% (ngang đoán mò 25%), cặp trùng nhiều nhất ${ac.tnMax}/${ac.nT} câu;` : ''}${ac.nD ? ` đúng – sai trùng nguyên bảng Đ/S ${Math.round(ac.dsSame*1000)/10}% số cặp câu;` : ''}${ac.nL ? ` trả lời ngắn ${ac.tlDup ? ac.tlDup + ' đáp số trùng (câu cố định hoặc ít bộ số)' : 'đáp số khác nhau ở mọi vị trí câu'}.` : ''}`);
  log(`Đã trộn thành ${variants.length} mã đề từ ${filledRoots.length} mã đề gốc (gốc số ${filledRoots.map(x=>x.i+1).join(', ')}), xếp xen kẽ các gốc.${state.mixThaySo === false ? '' : ` Thay số ${nRe}/${nAll} câu (câu thay số mỗi mã đề một bộ số khác) — không có hai mã đề giống hệt nhau.`}`);
  renderStep4();
}

/* ============================================================
   6. XUẤT LATEX
   ============================================================ */
/* ---------- BẢNG TỌA ĐỘ PHIẾU TRẢ LỜI (dùng chung cho vẽ phiếu và đọc phiếu offline) ----------
   Đơn vị: mm theo ảnh mẫu (x sang phải, y xuống dưới). Tâm 4 ô vuông định vị: xem OMR_MARKERS. */
const OMR_MARKERS = {TL:[3.9,4.2], TR:[139.9,4.2], BL:[3.9,99.1], BR:[139.9,99.1], size:4.2};
/* V1.74: MÃ BÀI trên phiếu đề thi giữa kỳ, cuối kỳ — dải ô vuông ở mép đáy, xen giữa 5 vạch định vị: 20 bit mã + 6 bit kiểm tra.
   Phiếu cũ (không có ô nào) đọc ra mã 0 → chấm như trước. Mã lấy từ bộ đếm chung như phiếu ôn luyện. */
const OMR_AK = (()=>{ const xs = []; [[7.6, 29.4], [34.4, 50.3], [55.7, 71.6], [77.0, 92.9], [98.4, 114.3], [119.6, 135.6]].forEach(([a, b])=>{ for(let x = a + 1.1; x + 1.1 <= b + 0.01; x += 3) xs.push(Math.round(x*100)/100); }); return xs.slice(0, 26); })();
function omrAkCheck(id){ return ((id ^ (id >> 6) ^ (id >> 12) ^ (id >> 18)) & 63) ^ 42; }
function omrAkBits(id){ if(!(id > 0)) return []; const c = omrAkCheck(id), b = []; for(let i = 0; i < 20; i++) b.push((id >> i) & 1); for(let i = 0; i < 6; i++) b.push((c >> i) & 1); return b; }
function omrReadAk(gray, w, h, map, loc){ const mid = (loc.dark + loc.paper)/2, ms = OMR_AK.map(x=> omrMeanGray(gray, w, h, map, x, 98.1, 0.6)), bits = ms.map(m=> m < mid ? 1 : 0);
  if(!bits.some(x=> x)) return 0; let id = 0, c = 0; for(let i = 0; i < 20; i++) id |= bits[i] << i; for(let i = 0; i < 6; i++) c |= bits[20 + i] << i;
  return c === omrAkCheck(id) && id > 0 ? id : -1; }   // -1: có dải mã nhưng đọc không chắc
function omrLayout(){
  const digits = '0123456789'.split('');
  const L = {sbd:[], made:[], p1:[], p2:[], p3:[]};
  for(let i=0;i<8;i++) L.sbd.push(digits.map((v,d)=>({x:14.0+i*3.1, y:15.2+d*3.13, v})));
  for(let i=0;i<4;i++) L.made.push(digits.map((v,d)=>({x:44.7+i*3.1, y:15.2+d*3.13, v})));
  for(let c=0;c<3;c++) for(let r=0;r<6;r++){
    const x0 = 56.7 + c*18.2, y = 27.7 + r*3.14;
    L.p1[c*6+r] = ['A','B','C','D'].map((v,k)=>({x:x0+5.9+k*3.1, y, v}));
  }
  for(let q=0;q<4;q++){
    const bx = (q%2===0) ? 111.2 : 123.5, by = (q<2) ? 8.3 : 27.2;
    L.p2.push([0,1,2,3].map(j=>{ const y = by + 6.1 + j*3.33; return [{x:bx+6.4, y, v:'Đ'}, {x:bx+9.4, y, v:'S'}]; }));
  }
  for(let c=0;c<6;c++){
    const x0 = 8 + c*21.3;
    const dcol = dx=> digits.map((v,d)=>({x:x0+dx, y:64.1+d*3.12, v}));
    L.p3.push([
      [{x:x0+6.0, y:57.9, v:'-'}, ...dcol(6.0)],
      [{x:x0+10.2, y:61, v:','}, ...dcol(10.2)],
      [{x:x0+14.3, y:61, v:','}, ...dcol(14.3)],
      dcol(18.4)
    ]);
  }
  return L;
}
/* V14.3: cách đánh số câu của đề định kỳ — 'lienTuc': Câu 1 → Câu N xuyên suốt các phần (phiếu trả lời đánh số theo đó);
   'theoPhan': mỗi phần đánh lại từ Câu 1 (phiếu như cũ). Phần I luôn bắt đầu từ câu 1. */
function examNumCont(){ return state.examNumbering !== 'theoPhan'; }
function examNumOffsets(){ const c = omrExamCounts(), on = examNumCont(); return {DS: on ? c.nTN : 0, TLN: on ? c.nTN + c.nDS : 0, TL: on ? c.nTN + c.nDS + c.nTLN : 0}; }
function examNumSelectHtml(onchange){ return `<label class="small-text" style="margin:0" title="Phiếu trả lời tự đánh số khớp với đề">Đánh số câu: <select onchange="state.examNumbering=this.value; saveLocal(); ${onchange}">
  <option value="lienTuc" ${examNumCont()?'selected':''}>liên tục Câu 1 → Câu ${(()=>{ const c = omrExamCounts(); return c.nTN + c.nDS + c.nTLN + ((state.variants[0]||{}).TL||[]).length; })()}</option>
  <option value="theoPhan" ${examNumCont()?'':'selected'}>đánh lại từ Câu 1 ở mỗi phần</option></select></label>`; }
function buildOmrSheetTikz(){
  const OFF = examNumOffsets(), CNT = omrExamCounts(), CONT = examNumCont();
  // đánh số liên tục: dòng / câu không dùng của mỗi phần để trống (không số, không ô) để học sinh không tô nhầm sang phần khác
  const useTN = r=> !CONT || r < CNT.nTN, useDS = q=> !CONT || !CNT.nDS || q < CNT.nDS, useTLN = c=> !CONT || !CNT.nTLN || c < CNT.nTLN;
  // Toạ độ đo theo ảnh mẫu (1 đơn vị = 10px ảnh ≈ 1mm), trục y hướng xuống; cả khối được co giãn vừa \textwidth nên giữ đúng tỉ lệ.
  const L = [];
  const P = s=> L.push(s);
  const f = n=> (Math.round(n*100)/100).toString();
  const sq = (x1,y1,x2,y2)=> P(`\\fill (${f(x1)},${f(y1)}) rectangle (${f(x2)},${f(y2)});`);
  const bub = (x,y)=> P(`\\draw[line width=0.3pt] (${f(x)},${f(y)}) circle (1.05mm);`);
  const lab = (x,y,s,opt)=> P(`\\node[${opt||'lb'}] at (${f(x)},${f(y)}) {${s}};`);
  const line = (x1,y1,x2,y2,opt)=> P(`\\draw[${opt||'line width=0.6pt'}] (${f(x1)},${f(y1)}) -- (${f(x2)},${f(y2)});`);
  const kythi = KYTHI_LABEL[state.kytha] || '';

  // 4 góc định vị + vạch định vị đáy
  sq(1.8,2.2,6,6.2); sq(137.8,2.2,142,6.2); sq(1.8,97,6,101.2); sq(137.8,97,142,101.2);
  [31.7,53,74.3,95.7,117].forEach(cx=> sq(cx-1.1,97,cx+1.1,99.2));
  omrAkBits(state.examAk).forEach((b, i)=>{ if(b) sq(OMR_AK[i]-1.1,97,OMR_AK[i]+1.1,99.2); });   // V1.74: mã bài

  // Tiêu đề, chữ dọc bên trái
  lab(72,3.1,'PHIẾU TRẢ LỜI TRẮC NGHIỆM','tt');
  lab(3.9,30.5,`${state.info.truong} — ${kythi}`,'side');

  // Khung trên
  P(`\\draw[line width=0.6pt] (8,8.3) rectangle (135.8,46.2);`);
  line(38.7,8.3,38.7,46.2); line(56.7,8.3,56.7,46.2); line(111.2,8.3,111.2,46.2);
  line(56.7,21.5,111.2,21.5); line(74.9,21.5,74.9,46.2); line(93.1,21.5,93.1,46.2);
  line(123.5,8.3,123.5,46.2); line(111.2,27.2,135.8,27.2);
  lab(9,6.1,'Số báo danh','lbw'); lab(39.8,6.1,'Mã đề','lbw'); lab(112.8,5.9,'PHẦN II','hdw');

  // Số báo danh: 8 ô viết + 8 cột tô
  P(`\\draw[line width=0.3pt] (12.4,10) rectangle (37.3,13);`);
  for(let i=1;i<8;i++) line(12.4+i*3.1125,10,12.4+i*3.1125,13,'line width=0.3pt');
  for(let d=0; d<10; d++){
    const y = 15.2 + d*3.13;
    lab(10.2,y,d,'dg');
  }

  // Mã đề: 4 ô viết (in sẵn mã đề) + 4 cột tô
  sq(39.8,10.8,42,13);
  P(`\\draw[line width=0.3pt] (43.2,10) rectangle (55.5,13);`);
  for(let i=1;i<4;i++) line(43.2+i*3.075,10,43.2+i*3.075,13,'line width=0.3pt');
  for(let d=0; d<10; d++){
    const y = 15.2 + d*3.13;
    lab(40.8,y,d,'dg');
  }

  // Thông tin thí sinh
  const dots = (name,x,y,text,xEnd)=>{
    P(`\\node[lbw] (${name}) at (${f(x)},${f(y)}) {${text}};`);
    P(`\\draw[dotted,line width=0.5pt] ([xshift=0.8mm]${name}.base east) -- (${f(xEnd)},0 |- ${name}.base east);`);
  };
  // V14.4: ô thông tin rộng, chữ to hơn để dễ ghi; điểm có ô riêng đủ chỗ viết (vùng này không có ô tô nên không ảnh hưởng việc đọc phiếu)
  const dotsB = (name,x,y,text,xEnd)=>{
    P(`\\node[nm] (${name}) at (${f(x)},${f(y)}) {${text}};`);
    P(`\\draw[dotted,line width=0.6pt] ([xshift=0.8mm]${name}.base east) -- (${f(xEnd)},0 |- ${name}.base east);`);
  };
  dotsB('ht',58.2,10.9,'Họ và tên:',109.8);
  dotsB('lop',58.2,15.7,'Lớp:',75.2);
  dotsB('mon',76.4,15.7,'Môn:',92.6);
  P(`\\draw[line width=0.6pt] (94,12.9) rectangle (111.2,21.5);`);
  P(`\\node[nm,anchor=north west] at (94.6,13.4) {\\textbf{Điểm}};`);
  lab(58.2,20.1,'PHẦN I','hdw');

  // Phần I: 3 cột × 6 câu = 18 câu
  for(let c=0;c<3;c++){
    const x0 = 56.7 + c*18.2;
    sq(x0+1.1,23.3,x0+3.3,25.5);
    ['A','B','C','D'].forEach((o,k)=> lab(x0+5.9+k*3.1,24.4,o,'dg'));
    for(let r=0;r<6;r++){
      const y = 27.7 + r*3.14;
      if(useTN(c*6+r)) lab(x0+1.1,y,c*6+r+1,'dgw');
    }
  }

  // Phần II: 4 câu, mỗi câu 4 ý a–d, tô Đ/S
  for(let q=0;q<4;q++){
    const bx = (q%2===0) ? 111.2 : 123.5;
    const by = (q<2) ? 8.3 : 27.2;
    if(q%2===0) sq(bx+1.6,by+1.7,bx+3.8,by+3.9);
    lab(bx+6.4,by+2.9,'Đ','sm'); lab(bx+9.4,by+2.9,'S','sm');
    ['a','b','c','d'].forEach((p,j)=>{
      const y = by + 6.1 + j*3.33;
      if(useDS(q)) lab(bx+(OFF.DS+q+1 >= 10 ? 2.4 : 2.7),y,`${OFF.DS+q+1}${p})`, OFF.DS+q+1 >= 10 ? 'sm' : 'dg');
    });
  }

  // Phần III: 6 câu, mỗi câu 4 cột ký tự (dấu - chỉ ở cột 1, dấu phẩy ở cột 2-3)
  lab(9.3,49,'PHẦN III','hdw');
  P(`\\draw[line width=0.6pt] (8,51.8) rectangle (135.8,95);`);
  for(let c=1;c<6;c++) line(8+c*21.3,51.8,8+c*21.3,95);
  for(let c=0;c<6;c++){
    const x0 = 8 + c*21.3;
    sq(x0+1.3,53.5,x0+3.5,55.7);
    if(useTLN(c)) lab(x0+5,54.6,`Câu ${OFF.TLN+c+1}`,'hdw');
    lab(x0+2.3,57.9,'-','dg');
    lab(x0+2.3,61,',','dg');
    for(let d=0; d<10; d++){
      const y = 64.1 + d*3.12;
      lab(x0+2.3,y,d,'dg');
    }
  }

  // Toàn bộ ô tròn vẽ từ bảng tọa độ chung omrLayout() — cũng là bảng bộ đọc phiếu offline dùng để đo.
  { const Lb = omrLayout(); Lb.sbd.flat().concat(Lb.made.flat()).forEach(b=> bub(b.x, b.y));
    Lb.p1.forEach((g,r)=>{ if(useTN(r)) g.forEach(b=> bub(b.x, b.y)); });
    Lb.p2.forEach((g,q)=>{ if(useDS(q)) g.flat().forEach(b=> bub(b.x, b.y)); });
    Lb.p3.forEach((g,c)=>{ if(useTLN(c)) g.flat().forEach(b=> bub(b.x, b.y)); }); }
  return `\\begin{tikzpicture}[x=1mm,y=-1mm,every node/.style={inner sep=0pt},
  lb/.style={font=\\fontsize{6}{7}\\selectfont},
  lbw/.style={font=\\fontsize{6}{7}\\selectfont,anchor=west},
  hdw/.style={font=\\fontsize{6}{7}\\selectfont\\bfseries,anchor=west},
  dg/.style={font=\\fontsize{5.5}{6}\\selectfont\\bfseries},
  dgw/.style={font=\\fontsize{5.5}{6}\\selectfont\\bfseries,anchor=west},
  sm/.style={font=\\fontsize{4.5}{5}\\selectfont\\bfseries},
  nm/.style={font=\\fontsize{7.5}{9}\\selectfont,anchor=west},
  md/.style={font=\\fontsize{7}{8}\\selectfont\\bfseries},
  tt/.style={font=\\fontsize{10}{12}\\selectfont\\bfseries},
  side/.style={font=\\fontsize{6}{7}\\selectfont,rotate=90}]
\\path (0,0) rectangle (144,102.5);
${L.join('\n')}
\\end{tikzpicture}`;
}
/* V1.18: PHIẾU TÔ trong bản in PDF — vẽ bằng SVG theo ĐÚNG toạ độ của phiếu LaTeX (buildOmrSheetTikz) và bảng omrLayout(),
   nên bộ đọc phiếu offline ở bước Chấm bài đọc được như phiếu cũ. f = {name, lop, mon, sbd, made, fill}: điền sẵn chữ; fill = tô sẵn ô SBD, mã đề. */
function buildOmrSheetSvg(f){
  f = f || {};
  const OFF = examNumOffsets(), CNT = omrExamCounts(), CONT = examNumCont();
  const useTN = r=> !CONT || r < CNT.nTN, useDS = q=> !CONT || !CNT.nDS || q < CNT.nDS, useTLN = c=> !CONT || !CNT.nTLN || c < CNT.nTLN;
  const pt = s=> (s*0.3528).toFixed(2), r2 = n=> (Math.round(n*100)/100);
  const E = s=> String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const FS = {lb:[6,0], lbw:[6,0], hdw:[6,1], dg:[5.5,1], dgw:[5.5,1], sm:[4.5,1], nm:[7.5,0], tt:[10,1], side:[6,0], wr:[7.5,1]};
  const o = [], P = s=> o.push(s);
  const sq = (x1,y1,x2,y2)=> P(`<rect x="${r2(x1)}" y="${r2(y1)}" width="${r2(x2-x1)}" height="${r2(y2-y1)}" fill="#000"/>`);
  const rect = (x1,y1,x2,y2,w)=> P(`<rect x="${r2(x1)}" y="${r2(y1)}" width="${r2(x2-x1)}" height="${r2(y2-y1)}" fill="none" stroke="#000" stroke-width="${w||0.21}"/>`);
  const line = (x1,y1,x2,y2,w,dash)=> P(`<line x1="${r2(x1)}" y1="${r2(y1)}" x2="${r2(x2)}" y2="${r2(y2)}" stroke="#000" stroke-width="${w||0.21}"${dash ? ` stroke-dasharray="${dash}" stroke-linecap="round"` : ''}/>`);
  const lab = (x,y,s,st)=>{ st = st || 'lb'; const [z, b] = FS[st] || FS.lb, west = /w$|^nm$/.test(st);
    const tr = st === 'side' ? ` transform="rotate(-90 ${r2(x)} ${r2(y)})"` : '';
    P(`<text x="${r2(x)}" y="${r2(y)}" font-size="${pt(z)}"${b ? ' font-weight="bold"' : ''} text-anchor="${west ? 'start' : 'middle'}" dominant-baseline="central"${tr}>${E(s)}</text>`); };
  const bub = (x,y,on)=> P(`<circle cx="${r2(x)}" cy="${r2(y)}" r="1.05" fill="${on ? '#000' : 'none'}" stroke="#000" stroke-width="0.106"/>`);
  const kythi = KYTHI_LABEL[state.kytha] || '';
  // góc định vị + vạch đáy
  sq(1.8,2.2,6,6.2); sq(137.8,2.2,142,6.2); sq(1.8,97,6,101.2); sq(137.8,97,142,101.2);
  [31.7,53,74.3,95.7,117].forEach(cx=> sq(cx-1.1,97,cx+1.1,99.2));
  omrAkBits(state.examAk).forEach((b, i)=>{ if(b) sq(OMR_AK[i]-1.1,97,OMR_AK[i]+1.1,99.2); });   // V1.74: mã bài
  lab(72,3.1,'PHIẾU TRẢ LỜI TRẮC NGHIỆM','tt');
  lab(3.9,30.5,`${state.info.truong||''} — ${kythi}`,'side');
  rect(8,8.3,135.8,46.2,0.21);
  [[38.7,8.3,38.7,46.2],[56.7,8.3,56.7,46.2],[111.2,8.3,111.2,46.2],[56.7,21.5,111.2,21.5],[74.9,21.5,74.9,46.2],[93.1,21.5,93.1,46.2],[123.5,8.3,123.5,46.2],[111.2,27.2,135.8,27.2]].forEach(a=> line(...a));
  lab(9,6.1,'Số báo danh','lbw'); lab(39.8,6.1,'Mã đề','lbw'); lab(112.8,5.9,'PHẦN II','hdw');
  // SBD: 8 ô viết
  rect(12.4,10,37.3,13,0.106); for(let i=1;i<8;i++) line(12.4+i*3.1125,10,12.4+i*3.1125,13,0.106);
  for(let d=0; d<10; d++) lab(10.2,15.2+d*3.13,d,'dg');
  const sbd = String(f.sbd||'').replace(/\D/g,''), made = String(f.made||'').replace(/\D/g,'');
  sbd.slice(0,8).split('').forEach((c,i)=> lab(12.4+(i+0.5)*3.1125,11.55,c,'wr'));
  // Mã đề: 4 ô viết
  sq(39.8,10.8,42,13); rect(43.2,10,55.5,13,0.106); for(let i=1;i<4;i++) line(43.2+i*3.075,10,43.2+i*3.075,13,0.106);
  for(let d=0; d<10; d++) lab(40.8,15.2+d*3.13,d,'dg');
  made.slice(0,4).split('').forEach((c,i)=> lab(43.2+(i+0.5)*3.075,11.55,c,'wr'));
  // thông tin thí sinh (chữ cỡ 7,5pt; dòng chấm nối tới mép ô)
  const dotsB = (x,y,text,xEnd,w,val)=>{ lab(x,y,text,'nm'); line(x+w+0.8,y+0.95,xEnd,y+0.95,0.21,'0 0.6');
    if(val) P(`<text x="${r2(x+w+1.6)}" y="${r2(y+0.55)}" font-size="${pt(String(val).length > 26 ? 6.6 : 7.5)}" font-weight="bold" font-style="italic">${E(val)}</text>`); };
  dotsB(58.2,10.9,'Họ và tên:',109.8,12.6,f.name);
  dotsB(58.2,15.7,'Lớp:',75.2,5.6,f.lop);
  dotsB(76.4,15.7,'Môn:',92.6,6.4,f.mon);
  rect(94,12.9,111.2,21.5,0.21);
  P(`<text x="94.6" y="13.4" font-size="${pt(7.5)}" font-weight="bold" dominant-baseline="hanging">Điểm</text>`);
  lab(58.2,20.1,'PHẦN I','hdw');
  for(let c=0;c<3;c++){ const x0 = 56.7 + c*18.2; sq(x0+1.1,23.3,x0+3.3,25.5);
    ['A','B','C','D'].forEach((t,k)=> lab(x0+5.9+k*3.1,24.4,t,'dg'));
    for(let r=0;r<6;r++) if(useTN(c*6+r)) lab(x0+1.1,27.7+r*3.14,c*6+r+1,'dgw'); }
  for(let q=0;q<4;q++){ const bx = (q%2===0) ? 111.2 : 123.5, by = (q<2) ? 8.3 : 27.2;
    if(q%2===0) sq(bx+1.6,by+1.7,bx+3.8,by+3.9);
    lab(bx+6.4,by+2.9,'Đ','sm'); lab(bx+9.4,by+2.9,'S','sm');
    ['a','b','c','d'].forEach((p,j)=>{ const y = by + 6.1 + j*3.33, n = OFF.DS+q+1;
      if(useDS(q)) lab(bx+(n >= 10 ? 2.4 : 2.7),y,`${n}${p})`, n >= 10 ? 'sm' : 'dg'); }); }
  lab(9.3,49,'PHẦN III','hdw');
  rect(8,51.8,135.8,95,0.21); for(let c=1;c<6;c++) line(8+c*21.3,51.8,8+c*21.3,95);
  for(let c=0;c<6;c++){ const x0 = 8 + c*21.3; sq(x0+1.3,53.5,x0+3.5,55.7);
    if(useTLN(c)) lab(x0+5,54.6,`Câu ${OFF.TLN+c+1}`,'hdw');
    lab(x0+2.3,57.9,'-','dg'); lab(x0+2.3,61,',','dg');
    for(let d=0; d<10; d++) lab(x0+2.3,64.1+d*3.12,d,'dg'); }
  // ô tròn — cùng bảng toạ độ với bộ đọc phiếu; tô sẵn SBD (đủ 8 chữ số) và mã đề (đủ 4 chữ số)
  const Lb = omrLayout(), fillS = f.fill && sbd.length === 8, fillM = f.fill && made.length === 4;
  Lb.sbd.forEach((col,i)=> col.forEach(b=> bub(b.x, b.y, fillS && b.v === sbd[i])));
  Lb.made.forEach((col,i)=> col.forEach(b=> bub(b.x, b.y, fillM && b.v === made[i])));
  Lb.p1.forEach((g,r)=>{ if(useTN(r)) g.forEach(b=> bub(b.x, b.y)); });
  Lb.p2.forEach((g,q)=>{ if(useDS(q)) g.flat().forEach(b=> bub(b.x, b.y)); });
  Lb.p3.forEach((g,c)=>{ if(useTLN(c)) g.flat().forEach(b=> bub(b.x, b.y)); });
  if(state.examAk > 0) P(`<text x="8" y="3.5" font-size="${pt(6)}" font-weight="bold" dominant-baseline="central">Mã bài: ${state.examAk}</text>`);   // V1.74 (góc trái, tránh các điểm kiểm tra hướng phiếu ở dải trên)
  return `<svg class="omr-svg" viewBox="0 0 144 102.5" xmlns="http://www.w3.org/2000/svg" font-family="Times New Roman, Times, serif" style="width:100%;height:auto;display:block">${o.join('')}</svg>`;
}
function dotLinesMacroLatex(){
  // Kẻ dòng .\dotfill\\[0.28cm] cho đến hết trang hiện tại (tự tính số dòng còn vừa).
  return `\\makeatletter
\\@ifundefined{mbpDotN}{\\newcount\\mbpDotN}{}
\\makeatother
\\providecommand{\\mbpDotLinesRest}{\\par
  \\ifdim\\pagegoal=\\maxdimen
    \\mbpDotN=\\numexpr\\dimexpr\\textheight-\\topskip+\\baselineskip+0.28cm-0.5\\baselineskip-0.14cm\\relax/\\dimexpr\\baselineskip+0.28cm\\relax\\relax
  \\else
    \\mbpDotN=\\numexpr\\dimexpr\\pagegoal-\\pagetotal+0.28cm-0.5\\baselineskip-0.14cm\\relax/\\dimexpr\\baselineskip+0.28cm\\relax\\relax
  \\fi
  \\ifnum\\mbpDotN>0 \\noindent
    \\loop\\ifnum\\mbpDotN>1 .\\dotfill\\\\[0.28cm]\\advance\\mbpDotN by -1 \\repeat
    .\\dotfill\\par
  \\fi}
`;
}
function examHasTL(){ const v = (state.variants||[])[0] || (state.roots||[]).find(r=> r) || {}; return (v.TL||[]).length > 0 || (!(state.variants||[]).length && +state.soCauTuLuan > 0); }
function buildBubbleSheetLatex(){
  // Trang 1: phiếu trả lời; phần còn lại trang 1 + toàn bộ trang 2: dòng kẻ chấm; đề bắt đầu từ trang 3.
  // V1.29: đề không có tự luận → chỉ một trang phiếu, không kẻ dòng chấm
  if(!examHasTL()) return `\\thispagestyle{empty}
\\noindent\\resizebox{\\textwidth}{!}{%
${buildOmrSheetTikz()}%
}
\\newpage
`;
  return `${dotLinesMacroLatex()}\\thispagestyle{empty}
\\noindent\\resizebox{\\textwidth}{!}{%
${buildOmrSheetTikz()}%
}
\\par\\vspace{3mm}
\\mbpDotLinesRest
\\newpage
\\thispagestyle{empty}
\\mbpDotLinesRest
\\newpage
`;
}
function headerData(v){
  const up = s=> String(s||'').toLocaleUpperCase('vi');
  const truong = String(state.info.truong||'').trim();
  return {
    TRUONG: truong, TO: state.info.to, KYTHI: KYTHI_LABEL[state.kytha],
    NAMHOC: state.info.namHoc, MONHOC: state.info.monHoc, LOP: state.grade,
    THOIGIAN: state.info.thoiGian, MADE: v ? v.code : '',
    SOGD: up(state.info.soGD || 'SỞ GDĐT'),
    TRUONG_HOA: up(/^trường/i.test(truong) ? truong : 'Trường '+truong),
    KYTHI_HOA: up(KYTHI_LABEL[state.kytha]),
    MONHOC_HOA: up(state.info.monHoc),
    NAMHOC_SP: String(state.info.namHoc||'').replace(/\s*-\s*/,' - '),
    SOTRANG: v ? `\\mbpSoTrang{mbpEnd${v.code}}` : ''
  };
}
function migrateTemplates(){
  // Mẫu mặc định cũ (chưa có tiêu đề 2 khối của trường) → thay 1 lần bằng mẫu mới; sau đó mẫu thầy tự sửa được giữ nguyên.
  if(state.templates && typeof state.templates.header==='string' && !state.templates._hdrV2){
    const h = state.templates.header;
    if(!h.includes('{{SOGD}}') && (/SỞ GD\\*&ĐT/.test(h) || h.includes('Đề thi sinh bởi công cụ'))){
      state.templates.header = defaultTemplates().header;
    }
    state.templates._hdrV2 = true;
  }
  if(state.info && !state.info.soGD) state.info.soGD = 'SỞ GDĐT THÁI NGUYÊN';
  if(!(state.startCode>=1000 && state.startCode<=9999)) state.startCode = 1001;
}
function splitHeaderAtDocument(hdr){
  const key = '\\begin{document}';
  const i = hdr.indexOf(key);
  if(i<0) return {pre:'', title:hdr};
  return {pre: hdr.slice(0, i+key.length) + '\n', title: hdr.slice(i+key.length)};
}
function ensureExamPackages(pre){
  const need = [['graphicx','\\usepackage{graphicx}'],['tikz','\\usepackage{tikz}'],['tkz-tab','\\usepackage{tkz-tab}'],['fancyhdr','\\usepackage{fancyhdr}'],['lastpage','\\usepackage{lastpage}'],['refcount','\\usepackage{refcount}']];
  let add = '';
  need.forEach(([name,line])=>{ if(!new RegExp('\\\\usepackage(\\[[^\\]]*\\])?\\{[^}]*\\b'+name+'\\b').test(pre)) add += line+'\n'; });
  if(!add) return pre;
  return pre.replace('\\begin{document}', add + '\\begin{document}');
}
function examFooterSetupLatex(v){
  const kythi = KYTHI_LABEL[state.kytha] || '';
  return `% Đếm số trang của riêng mã đề này qua nhãn mbpEnd<mã đề> đặt ở cuối đề (có refcount thì in dạng 02, không có thì in 2)
\\makeatletter
\\providecommand{\\mbpSoTrang}[1]{\\@ifundefined{getpagerefnumber}{\\pageref{#1}}{\\ifnum\\getpagerefnumber{#1}<10 0\\fi\\getpagerefnumber{#1}}}
\\makeatother
\\setcounter{page}{1}
\\pagestyle{fancy}\\fancyhf{}
\\renewcommand{\\headrulewidth}{0pt}
\\renewcommand{\\footrulewidth}{0.4pt}
\\fancyfoot[L]{\\small Mã đề ${v.code}}
\\fancyfoot[C]{\\small ${kythi} — ${state.info.monHoc} ${state.grade} — ${state.info.namHoc}}
\\fancyfoot[R]{\\small Trang \\thepage/\\pageref{mbpEnd${v.code}}}
`;
}
function renderAnswerSheetLatex(noPreamble){
  // 1 phiếu chung cho mọi mã đề (học sinh tự viết và tô mã đề): trang 1 phiếu trả lời, trang 2 giấy làm bài kẻ chấm.
  const T = state.templates;
  if(noPreamble){
    return `% ====== Phiếu trả lời chung cho mọi mã đề — không kèm preamble ======\n% Tài liệu đích cần có: \\usepackage{tikz}, \\usepackage{graphicx}\n` + buildBubbleSheetLatex();
  }
  const hdr = tpl(T.header, headerData(null));
  const parts = splitHeaderAtDocument(hdr);
  return ensureExamPackages(parts.pre) + buildBubbleSheetLatex() + '\\end{document}\n';
}
function renderAnswerKeyLatex(noPreamble){
  // 1 file đáp án tổng hợp cho tất cả mã đề: mỗi phần 1 bảng (hàng = mã đề, cột = câu, đánh số trong từng phần như phiếu trả lời).
  const vs = state.variants || [];
  const T = state.templates;
  const H = headerData(null);
  const clean = s=> String(s==null?'':s).trim().replace(/\.+$/,'');
  const table = (title, nCols, rowFn, start)=>{ start = start || 0;
    if(!nCols) return '';
    const spec = '|c|' + 'c|'.repeat(nCols);
    let t = `\\subsection*{${title}}\n{\\small\n\\begin{longtable}{${spec}}\n\\hline\n\\textbf{Mã đề}`;
    for(let i=1;i<=nCols;i++) t += ` & \\textbf{${start+i}}`;
    t += ` \\\\\n\\hline\n\\endhead\n`;
    vs.forEach(v=>{ t += `${v.code} & ${rowFn(v).join(' & ')} \\\\\n\\hline\n`; });
    return t + `\\end{longtable}\n}\n`;
  };
  const maxLen = k=> vs.reduce((m,v)=> Math.max(m, (v[k]||[]).length), 0);
  const pad = (arr,n)=> { const a = arr.slice(); while(a.length<n) a.push(''); return a; };
  let body = `\\begin{center}
{\\large\\textbf{ĐÁP ÁN — ĐỀ KIỂM TRA ${H.KYTHI_HOA} KHỐI ${H.LOP}}}\\\\
\\textbf{${H.TRUONG_HOA} — NĂM HỌC ${H.NAMHOC_SP} — Môn: ${H.MONHOC_HOA}}\\\\
\\textit{(Gồm ${vs.length} mã đề; số câu ${examNumCont() ? 'đánh liên tục qua các phần' : 'đánh riêng trong từng phần'}, khớp với đề và phiếu trả lời)}
\\end{center}
`;
  const nTN = maxLen('TN'), nDS = maxLen('DS'), nTLN = maxLen('TLN');
  body += table('Phần I. Trắc nghiệm nhiều lựa chọn', nTN, v=> pad((v.TN||[]).map(q=> q.dapan||''), nTN));
  const off = examNumCont() ? [nTN, nTN + nDS] : [0, 0];
  body += table('Phần II. Trắc nghiệm đúng sai (thứ tự ý a, b, c, d)', nDS, v=> pad((v.DS||[]).map(q=> (q.menhde||[]).map(mm=> mm.dung?'Đ':'S').join('')), nDS), off[0]);
  body += table('Phần III. Trắc nghiệm trả lời ngắn', nTLN, v=> pad((v.TLN||[]).map(q=> clean(q.dapan)), nTLN), off[1]);
  // Tự luận: gộp theo câu hỏi (các mã đề cùng câu gốc chỉ in 1 lần)
  const seen = new Map();
  vs.forEach(v=> (v.TL||[]).forEach(q=>{
    const key = String(q.cauhoi||'').trim();
    if(!key) return;
    if(!seen.has(key)) seen.set(key, {q, codes:[]});
    seen.get(key).codes.push(v.code);
  }));
  if(seen.size){
    body += `\\subsection*{Phần IV. Hướng dẫn giải tự luận}\n`;
    let i = 1;
    seen.forEach(({q,codes})=>{
      body += `\\noindent\\textbf{Câu hỏi ${i++}} \\textit{(mã đề: ${codes.join(', ')})}: ${q.cauhoi}\\\\\n\\textbf{Lời giải:} ${q.loigiai ? q.loigiai : '\\textit{(chưa có lời giải)}'}\\par\\medskip\n`;
    });
  }
  if(noPreamble){
    return `% ====== Đáp án tổng hợp — không kèm preamble (cần \\usepackage{longtable}) ======\n` + body;
  }
  let pre = splitHeaderAtDocument(tpl(T.header, H)).pre;
  if(!pre) pre = '\\documentclass[12pt,a4paper]{article}\n\\begin{document}\n';
  if(!/\\usepackage(\[[^\]]*\])?\{[^}]*\blongtable\b/.test(pre)) pre = pre.replace('\\begin{document}', '\\usepackage{longtable}\n\\begin{document}');
  return pre + '\\pagestyle{empty}\n' + body + '\\end{document}\n';
}
function downloadAnswerKey(){
  if(!state.variants.length){ alert('Chưa có mã đề nào. Hãy trộn mã đề ở bước 6.'); return; }
  download('dap_an_tong_hop.tex', renderAnswerKeyLatex(state.noPreamble));
}
function renderVariantLatex(v, includeAnswer, noPreamble, assetCollector){
  const T = state.templates;
  let out = '';
  if(!noPreamble){
    const hdr = tpl(T.header, headerData(v));
    const parts = splitHeaderAtDocument(hdr);
    out += ensureExamPackages(parts.pre);
    out += examFooterSetupLatex(v);
    out += parts.title.replace(/\\thispagestyle\{empty\}\s*/g,'');
  }else{
    out += `% ====== Mã đề ${v.code} — không kèm preamble, dán vào tài liệu LaTeX đã có sẵn ======\n% Tài liệu đích cần có: \\usepackage{tikz}, \\usepackage{tkz-tab}, \\usepackage{graphicx}, \\usepackage{fancyhdr}, \\usepackage{lastpage}, \\usepackage{refcount}\n`;
    out += examFooterSetupLatex(v);
    // Chỉ bỏ phần khai báo gói (preamble); khối tiêu đề đề thi vẫn giữ.
    out += splitHeaderAtDocument(tpl(T.header, headerData(v))).title.replace(/\\thispagestyle\{empty\}\s*/g,'');
  }
  let stt=1;
  const answerLines = [];
  function collectAsset(hinhVe){
    if(assetCollector && hinhVe && hinhVe.loai==='anh' && hinhVe.id && hinhVe.du_lieu){
      assetCollector.push({id: hinhVe.id, dataUrl: hinhVe.du_lieu});
    }
  }

  if(v.TN.length){
    out += T.tnHeader;
    v.TN.forEach(q=>{
      collectAsset(q.hinhVe);
      const stripTrailingDot = s=> String(s||'').trim().replace(/\.+$/,'');
      out += tpl(T.tnQuestion, {SOTT: stt, CAUHOI: (q.cauhoi||'')+questionHinhVeLatex(q.hinhVe), A:stripTrailingDot(q.A), B:stripTrailingDot(q.B), C:stripTrailingDot(q.C), D:stripTrailingDot(q.D)});
      answerLines.push(`Câu ${stt}: ${q.dapan}`);
      stt++;
    });
  }
  if(v.DS.length){
    out += T.dsHeader;
    if(!examNumCont()){ stt = 1; out += '\\ifcsname c@ex\\endcsname\\setcounter{ex}{0}\\fi\n'; }
    v.DS.forEach(q=>{
      collectAsset(q.hinhVe);
      const m = q.menhde||[];
      const noDot = s=> String(s||'').trim().replace(/\.+$/,'');
      out += tpl(T.dsQuestion, {SOTT: stt, DANNHAP: (q.dannhap||'')+questionHinhVeLatex(q.hinhVe), A:noDot(m[0]&&m[0].text), B:noDot(m[1]&&m[1].text), C:noDot(m[2]&&m[2].text), D:noDot(m[3]&&m[3].text)});
      answerLines.push(`Câu ${stt}: ` + m.map((mm,mi)=>`${mm.label||['a','b','c','d'][mi]}-${mm.dung?'Đ':'S'}`).join(', '));
      stt++;
    });
  }
  if(v.TLN.length){
    out += T.tlnHeader;
    if(!examNumCont()){ stt = 1; out += '\\ifcsname c@ex\\endcsname\\setcounter{ex}{0}\\fi\n'; }
    v.TLN.forEach(q=>{
      collectAsset(q.hinhVe);
      out += tpl(T.tlnQuestion, {SOTT: stt, CAUHOI: (q.cauhoi||'')+questionHinhVeLatex(q.hinhVe), DAPAN: q.dapan})
        .replace(/^[ \t]*\\shortans\{[^\n]*\}[ \t]*\n?/m, '');
      answerLines.push(`Câu ${stt}: ${q.dapan}`);
      stt++;
    });
  }
  if(v.TL.length){
    out += T.tlHeader;
    if(!examNumCont()){ stt = 1; out += '\\ifcsname c@ex\\endcsname\\setcounter{ex}{0}\\fi\n'; }
    v.TL.forEach(q=>{
      collectAsset(q.hinhVe);
      // Câu tự luận không chèn dòng kẻ chấm (học sinh làm bài trên giấy làm bài / phiếu trả lời).
      out += tpl(T.tlQuestion, {SOTT: stt, CAUHOI: (q.cauhoi||'')+questionHinhVeLatex(q.hinhVe), DOTFILL: ''});
      if(includeAnswer && q.loigiai) answerLines.push(`Câu ${stt}: ${q.loigiai}`);
      stt++;
    });
  }
  // Đáp án không in trong đề nữa — xuất riêng thành file dap_an_tong_hop.tex (renderAnswerKeyLatex).
  out += `\n\\label{mbpEnd${v.code}}\n`;
  if(!noPreamble) out += T.footer;
  return out;
}

function downloadAnswerSheet(){
  download('phieu_tra_loi.tex', renderAnswerSheetLatex(state.noPreamble));
  log('Đã xuất phiếu trả lời chung cho tất cả mã đề (phieu_tra_loi.tex).');
}
function standaloneTableDoc(body){
  // Bọc bảng ma trận / đặc tả thành tài liệu biên dịch được: dùng preamble của mẫu đề + các gói bảng cần thiết.
  const T = state.templates;
  const parts = splitHeaderAtDocument(tpl(T.header, headerData(null)));
  let pre = parts.pre;
  const need = ['pdflscape','multirow','array','graphicx','longtable'];
  let add = '';
  need.forEach(name=>{ if(!new RegExp('\\\\usepackage(\\[[^\\]]*\\])?\\{[^}]*\\b'+name+'\\b').test(pre)) add += '\\usepackage{'+name+'}\n'; });
  if(add) pre = pre.replace('\\begin{document}', add + '\\begin{document}');
  return pre + '\n' + body + '\n\\end{document}\n';
}
function examPackageFiles(){
  // Danh sách file trong bộ đề tải về (dùng cho cả nút tải và phần mô tả ở bước 7).
  const f = state.variants.map(v=> `made_${v.code}.tex`);
  f.push('phieu_tra_loi.tex', 'ma_tran_de.tex', 'ban_dac_ta.tex');
  if(state.includeAnswer) f.push('dap_an_tong_hop.tex');
  if(state.students.length) f.push('danh_sach_ma_de.csv');
  return f;
}
function downloadAllZip(){
  if(!state.variants.length){ alert('Chưa có mã đề nào. Hãy trộn mã đề ở bước 6.'); return; }
  const zip = new JSZip();
  const assets = [];
  state.variants.forEach(v=>{
    zip.file(`made_${v.code}.tex`, renderVariantLatex(v, state.includeAnswer, state.noPreamble, assets));
  });
  // Phiếu trả lời chung, ma trận đề và bản đặc tả luôn nằm trong bộ đề.
  zip.file('phieu_tra_loi.tex', renderAnswerSheetLatex(state.noPreamble));
  zip.file('ma_tran_de.tex', state.noPreamble ? buildMatrixLatex() : standaloneTableDoc(buildMatrixLatex()));
  zip.file('ban_dac_ta.tex', state.noPreamble ? buildSpecLatex() : standaloneTableDoc(buildSpecLatex()));
  if(state.includeAnswer) zip.file('dap_an_tong_hop.tex', renderAnswerKeyLatex(state.noPreamble));
  const seenAssets = new Set();
  assets.forEach(a=>{
    if(seenAssets.has(a.id)) return;
    seenAssets.add(a.id);
    const m = /^data:image\/(\w+);base64,(.*)$/.exec(a.dataUrl||'');
    if(!m) return;
    const ext = m[1]==='jpeg' ? 'jpg' : m[1];
    zip.file(`images/${a.id}.${ext}`, m[2], {base64:true});
  });
  if(seenAssets.size){
    log(`Đã đính kèm ${seenAssets.size} ảnh hình vẽ vào thư mục images/ trong file zip.`);
  }
  if(state.students.length){
    let csv = '\ufeffHọ và tên,Lớp,Số báo danh,Mã đề\n';
    state.students.forEach(s=> csv += `${s.name},${s.lop||''},${s.sbd||''},${s.made||''}\n`);
    zip.file('danh_sach_ma_de.csv', csv);
  }
  zip.generateAsync({type:'blob'}).then(blob=>{
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `MathBank_bo_de_lop${state.grade}_${state.kytha||'de'}.zip`;
    a.click();
    URL.revokeObjectURL(a.href);
    setTimeout(()=>{ try{ mbpAskSave('exam'); }catch(e){} }, 400);
  });
  log(`Đã tải bộ đề: ${examPackageFiles().length} file (${state.variants.length} mã đề, phiếu trả lời chung, ma trận, bản đặc tả${state.includeAnswer?', đáp án tổng hợp':''}${state.students.length?', danh sách mã đề':''}).`);
}

/* ============================================================
   7. GÁN MÃ ĐỀ CHO HỌC SINH
   ============================================================ */
function addStudentsBulk(text){
  text.split('\n').map(s=>s.trim()).filter(Boolean).forEach(name=>{
    state.students.push({name, made:null});
  });
}
function studentGrade(s){
  const m = /^(6|7|8|9|10|11|12)(?!\d)/.exec(String(s.lop||'').trim());
  return m ? m[1] : String(state.grade||10);
}
/* ---- Sổ số báo danh CỐ ĐỊNH (V14.9): mỗi học sinh một SBD dùng mãi — sinh lại không đổi số cũ, đổi khối (10A1 → 11A1) vẫn giữ ----
   SBD 8 chữ số = khối (2) + số lớp (2) + số thứ tự (4); số đã cấp không bao giờ cấp lại cho người khác. */
const sbdNorm = s=> String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[đĐ]/g,'d').toLowerCase().replace(/\s+/g,' ').trim();
const sbdClassKey = lop=> String(lop||'').toUpperCase().replace(/\s+/g,'').replace(/^(6|7|8|9|10|11|12)(?=[A-Z])/,'');   // "10A1" → "A1"
function sbdReg(){ if(!state.sbdReg || typeof state.sbdReg !== 'object') state.sbdReg = {map:{}, used:{}}; state.sbdReg.map = state.sbdReg.map || {}; state.sbdReg.used = state.sbdReg.used || {}; return state.sbdReg; }
// cấp SBD cố định cho cả danh sách [{name, lop, khoi?, sbd?}] — người cùng tên trong cùng lớp được đánh số #2, #3…
function sbdAssign(list){
  const R = sbdReg(), seen = {}; let added = 0;
  list.forEach(x=>{ const base = sbdNorm(x.name) + '|' + sbdClassKey(x.lop); seen[base] = (seen[base]||0) + 1; const key = base + (seen[base] > 1 ? '#' + seen[base] : '');
    if(R.map[key]){ x.sbd = R.map[key]; return; }
    if(x.sbd && /^\d{4,10}$/.test(String(x.sbd))){ R.map[key] = String(x.sbd); R.used[x.sbd] = key; return; }   // giữ SBD đã có sẵn (kể cả khi đổi tên lớp)
    const g = String(x.khoi || studentGrade(x)).padStart(2,'0'), cm = /(\d{1,2})\s*$/.exec(String(x.lop||'')), pre = g + (cm ? String(parseInt(cm[1])).padStart(2,'0') : '00');
    let n = 1, sbd = pre + '0001'; while(R.used[sbd] && n < 9999){ n++; sbd = pre + String(n).padStart(4,'0'); }   // số nhỏ nhất chưa từng cấp
    R.map[key] = sbd; R.used[sbd] = key; x.sbd = sbd; added++; });
  if(added) sbdRegPush();
  return added;
}
let _sbdPushT = null, _sbdPulled = false;
function sbdRegPush(){ clearTimeout(_sbdPushT); _sbdPushT = setTimeout(()=>{ putCloudJson('sbd_registry', sbdReg()).catch(()=>{}); }, 1500); }
// gộp sổ SBD trên máy chủ (dùng nhiều máy vẫn cùng một số)
async function sbdRegPull(){ if(_sbdPulled) return; _sbdPulled = true; try{ const c = await fetchCloudJson('sbd_registry'); if(c && c.map){ const R = sbdReg(); Object.assign(R.used, c.used || {}); Object.keys(c.map).forEach(k=>{ if(!R.map[k]) R.map[k] = c.map[k]; }); saveLocal(); } }catch(e){} }
function generateSBD(){
  if(!state.students.length){ alert('Chưa có học sinh nào trong danh sách.'); return; }
  const added = sbdAssign(state.students);
  saveLocal();
  log(`Số báo danh cố định: ${state.students.length - added} học sinh giữ số cũ, cấp mới ${added} học sinh (khối + lớp + số thứ tự, 8 chữ số — không đổi khi sinh lại).`);
  renderStep5();
}
function setStudentSBD(i, v){
  const d = String(v||'').replace(/\D/g,'').slice(0,8);
  if(d && state.students.some((s,j)=> j!==i && s.sbd===d)){ alert('Số báo danh '+d+' đã có học sinh khác dùng.'); renderStep5(); return; }
  state.students[i].sbd = d;
  saveLocal();
}
function assignCodes(){
  if(!state.students.length){ alert('Chưa có học sinh nào trong danh sách.'); return; }
  if(!state.variants || !state.variants.length){ alert('Chưa có mã đề nào — hãy trộn mã đề ở bước 6 trước khi gán.'); return; }
  if(state.students.length !== state.variants.length){
    const ok = confirm(`Số học sinh (${state.students.length}) khác số mã đề đã trộn (${state.variants.length}).\nBấm OK để trộn lại đúng ${state.students.length} mã đề, hoặc Cancel để gán vòng lặp với số mã đề hiện có.`);
    if(ok){ generateVariants(state.students.length); }
  }
  if(!state.variants.length) return;
  state.students.forEach((s,i)=>{
    s.made = state.variants[i % state.variants.length].code;
  });
  log('Đã gán mã đề cho từng học sinh.');
  renderStep5();
}

