(()=>{ try{ const o = JSON.parse(localStorage.getItem('mbp_wsCount') || 'null'); if(o){ if([8,9,10,11,12,13,14,15].includes(o.size)) wsOpt.size = o.size; if(o.ecoS) wsOpt.ecoS = o.ecoS; if(o.n >= 1 && o.n <= 40) wsOpt.n = o.n|0; if(typeof o.auto === 'boolean') wsOpt.auto = o.auto; if([1,2,3,4].includes(o.pages)) wsOpt.pages = o.pages; if(o.nS) wsOpt.nS = o.nS; } }catch(e){} if(!wsOpt.nS) wsOpt.nS = {}; })();   // V1.44: nhớ số câu, số trang, tự căn, số câu riêng từng loại phiếu
