const wsEcoOf = s=> wsOpt.ecoS && typeof wsOpt.ecoS[s] === 'boolean' ? wsOpt.ecoS[s] : !!wsOpt.eco;
const wsEcoAny = ()=> wsSheetsOn().some(wsEcoOf) || (wsOpt.key && wsEcoOf('key'));
