const TRIG_SOL = (fn, v)=>{ // nghiệm cơ bản trong [0; 2π)
  const a = fn==='sin' ? Math.asin(v) : Math.acos(v);
  const base = fn==='sin' ? [a, Math.PI-a] : [a, -a];
  return base;
};
const countSolutions = (fn, k, v, L, H)=>{ // đếm nghiệm của fn(kx) = v trên [L; H] bằng liệt kê họ nghiệm
  const base = TRIG_SOL(fn, v); const set = new Set();
  base.forEach(b=>{ for(let j=-40;j<=40;j++){ const x=(b+2*Math.PI*j)/k; if(x>=L-1e-9 && x<=H+1e-9) set.add(Math.round(x*1e9)); } });
  return set.size;
};
const scanRoots = (f, L, H, N)=>{ const r=[]; let prev=f(L); if(Math.abs(prev)<1e-12) r.push(L); for(let i=1;i<=N;i++){ const x=L+(H-L)*i/N, y=f(x); if(Math.abs(y)<1e-12) r.push(x); else if(prev*y<0 && Math.abs(prev)>=1e-12) r.push(x); prev=y; } return r; };
G(11,0,3,'TH','Số nghiệm của phương trình lượng giác trên một đoạn', R=>{
  const fn = R.pick(['sin','cos']), row = R.pick(SPECIAL_VALS.filter(([v])=> Math.abs(v)<1 && v!==0 && Math.abs(v)!==Math.sqrt(3) && Math.abs(v)!==Math.sqrt(3)/3));
  const [v, vT] = row, m = R.int(1,4);
  const cnt = countSolutions(fn, 1, v, 0, m*Math.PI);
  return {stem:`Số nghiệm của phương trình $\\${fn} x = ${vT}$ thuộc đoạn $[0; ${piT(m,1)}]$ là`,
    ans:T0(cnt), wrong:[cnt+1, cnt-1>0?cnt-1:cnt+2, 2*m, cnt+2, m].filter(x=>x!==cnt).map(T0),
    lg:`Biểu diễn các họ nghiệm của phương trình trên đường tròn lượng giác (hoặc liệt kê theo $k$) rồi chọn các nghiệm thuộc $[0; ${piT(m,1)}]$: có $${cnt}$ nghiệm.`,
    verify:()=> scanRoots(x=>Math[fn](x)-v, 0, m*Math.PI, 40000*m).length===cnt};
});
GT(11,0,3,'VD','Số nghiệm của phương trình sin kx = m, cos kx = m trên đoạn', R=>{
  const fn = R.pick(['sin','cos']), k = R.int(2,4), m = R.int(1,3);
  const [v, vT] = R.pick(SPECIAL_VALS.filter(([x])=> Math.abs(x)<1 && x!==0 && Math.abs(x)!==Math.sqrt(3) && Math.abs(x)!==Math.sqrt(3)/3));
  const cnt = countSolutions(fn, k, v, 0, m*Math.PI);
  return {stem:`Phương trình $\\${fn} ${k}x = ${vT}$ có bao nhiêu nghiệm thuộc đoạn $[0; ${piT(m,1)}]$?`, ans:cnt,
    lg:`Giải phương trình được các họ nghiệm dạng $x = \\dfrac{\\alpha + k2\\pi}{${k}}$; liệt kê các nghiệm thuộc $[0; ${piT(m,1)}]$ ta được $${cnt}$ nghiệm.`,
    verify:()=> scanRoots(x=>Math[fn](k*x)-v, 0, m*Math.PI, 60000*m*k).length===cnt};
});
GD(11,0,3,'TH','Phương trình sin x = m', R=>{
  const [v, vT] = R.pick(SPECIAL_VALS.filter(([x])=> Math.abs(x)<1 && x!==0 && Math.abs(x)!==Math.sqrt(3) && Math.abs(x)!==Math.sqrt(3)/3));
  const a = Math.asin(v), ap = Math.round(a/Math.PI*12); // α = ap/12 π
  const roots = scanRoots(x=>Math.sin(x)-v, 0, 2*Math.PI-1e-9, 72000);
  const sum = v>0 ? Math.PI : 3*Math.PI;
  const items = [
    claim(R, `Phương trình có một nghiệm là $x = ${piT(ap,12)}$`, `Phương trình có một nghiệm là $x = ${piT(-ap,12)}$`, ()=> near(Math.sin(ap/12*Math.PI), v, 1e-12), ()=> near(Math.sin(-ap/12*Math.PI), v, 1e-12)),
    claim(R, 'Phương trình có đúng $2$ nghiệm thuộc $[0; 2\\pi)$', 'Phương trình có đúng $1$ nghiệm thuộc $[0; 2\\pi)$', ()=> roots.length===2, ()=> roots.length===1),
    claimN(R, t=>`Tổng các nghiệm thuộc $[0; 2\\pi)$ của phương trình bằng $${t}$`, sum, piT(sum/Math.PI,1), 2*Math.PI, piT(2,1), ()=> roots.reduce((s,x)=>s+x,0)),
    claim(R, `Phương trình tương đương với $\\cos\\left(\\dfrac{\\pi}{2} - x\\right) = ${vT}$`, `Phương trình tương đương với $\\cos x = ${vT}$`, ()=> [0.3,1.2,2.6,4.1].every(x=> near(Math.cos(Math.PI/2-x), Math.sin(x), 1e-12)), ()=> [0.3,1.2,2.6,4.1].every(x=> near(Math.cos(x), Math.sin(x), 1e-12)))
  ];
  items[2].chk = ((c)=> ()=> Math.abs(roots.reduce((s,x)=>s+x,0) - (items[2].ok?sum:2*Math.PI)) < 1e-3)(items[2]);
  return {stem:`Cho phương trình $\\sin x = ${vT}$.`, items,
    lg:`$\\sin x = ${vT} \\Leftrightarrow x = ${piT(ap,12)} + k2\\pi$ hoặc $x = ${piT(12-ap,12)} + k2\\pi$. Trên $[0; 2\\pi)$ phương trình có $2$ nghiệm, tổng các nghiệm bằng $${piT(sum/Math.PI,1)}$; $\\cos\\left(\\dfrac{\\pi}{2} - x\\right) = \\sin x$.`};
});
// ---------- Dãy số ----------
G(11,1,0,'TH','Nhận biết dãy số tăng', R=>{
  const a = R.int(1,5), b = R.int(-5,5), c = R.int(1,4);
  const inc = R.pick([[`u_n = ${termsT([[a,'n'],[b,'']])}`, n=>a*n+b], [`u_n = ${polyT([1,0,b],'n')}`, n=>n*n+b], [`u_n = ${a+1}^n`, n=>(a+1)**n], [`u_n = \\dfrac{n}{n + ${c}}`, n=>n/(n+c)]]);
  const non = R.shuffle([[`u_n = ${termsT([[-a,'n'],[b,'']])}`, n=>-a*n+b], [`u_n = (-1)^n\\cdot n`, n=>(-1)**n*n], [`u_n = \\dfrac{1}{n + ${c}}`, n=>1/(n+c)], [`u_n = (-${a+1})^n`, n=>(-(a+1))**n], [`u_n = ${b}`, n=>b]]).slice(0,3);
  const isInc = f=>{ for(let n=1;n<30;n++) if(!(f(n+1)>f(n))) return false; return true; };
  return {stem:'Dãy số $(u_n)$ nào sau đây là dãy số tăng?', ans:{t:`$${inc[0]}$`, v:'i'}, wrong:non.map((x,i)=>({t:`$${x[0]}$`, v:'n'+i})),
    lg:`Với $${inc[0]}$ ta có $u_{n+1} - u_n > 0$ với mọi $n \\in \\mathbb{N}^*$ nên dãy tăng; các dãy còn lại giảm, không đổi hoặc không tăng không giảm.`,
    verify:()=> isInc(inc[1]) && non.every(x=>!isInc(x[1]))};
});
G(11,1,0,'TH','Dãy số cho bởi hệ thức truy hồi', R=>{
  const u1 = R.int(-4,5), p = R.pick([2,3,-2]), q = R.int(-4,4), k = R.pick([4,5]);
  let u = u1; for(let i=1;i<k;i++) u = p*u+q;
  const Lf = q/(1-p);
  return {stem:`Cho dãy số $(u_n)$ xác định bởi $u_1 = ${u1}$ và $u_{n+1} = ${termsT([[p,'u_n'],[q,'']])}$ với mọi $n \\geq 1$. Số hạng $u_{${k}}$ bằng`,
    ans:T0(u), wrong:[T0((u-q)/p), T0(p*u+q), T0(u1*p**(k-1)), T0(u+q)],
    lg:`Tính lần lượt $u_2, u_3, \\ldots$ theo công thức truy hồi, được $u_{${k}} = ${u}$.`,
    verify:()=> near(p**(k-1)*(u1-Lf)+Lf, u, 1e-9)};
});
GT(11,1,0,'TH','Tìm số thứ tự của một số hạng', R=>{
  const b = R.int(-1,6), c = R.int(-10,10), n0 = R.int(3,25);
  const m = n0*n0+b*n0+c;
  if(Math.abs(m)>9999) return null;
  return {stem:`Cho dãy số $(u_n)$ với $u_n = ${polyT([1,b,c],'n')}$. Số $${m}$ là số hạng thứ mấy của dãy số?`, ans:n0,
    lg:`Giải $${polyT([1,b,c],'n')} = ${m} \\Leftrightarrow ${polyT([1,b,c-m],'n')} = 0$, lấy nghiệm nguyên dương $n = ${n0}$.`,
    verify:()=>{ const f=[]; for(let n=1;n<=200;n++) if(n*n+b*n+c===m) f.push(n); return f.length===1 && f[0]===n0; }};
});
GD(11,1,0,'TH','Tính chất của dãy số cho bởi công thức', R=>{
  const a = R.nz(-4,5), b = R.int(-6,6), c = R.int(1,4);
  if(a*c-b===0) return null;
  const u = n=> (a*n+b)/(n+c);
  const k = R.int(2,8);
  const incr = a*c-b>0;
  const items = [
    claimN(R, v=>`$u_1 = ${v}$`, (a+b)/(1+c), frT(a+b,1+c), (a+b)/c, frT(a+b,c), ()=> u(1)),
    claim(R, `Dãy số $(u_n)$ là dãy số ${incr?'tăng':'giảm'}`, `Dãy số $(u_n)$ là dãy số ${incr?'giảm':'tăng'}`, ()=>{ for(let n=1;n<60;n++){ if(incr ? !(u(n+1)>u(n)) : !(u(n+1)<u(n))) return false; } return true; }, ()=>{ for(let n=1;n<60;n++){ if(incr ? !(u(n+1)<u(n)) : !(u(n+1)>u(n))) return false; } return true; }),
    claimN(R, v=>`$u_{${k}} = ${v}$`, u(k), frT(a*k+b,k+c), u(k+1), frT(a*(k+1)+b,k+1+c), ()=> (a*k+b)/(k+c)),
    claim(R, `$u_n ${incr?'<':'>'} ${a}$ với mọi $n \\in \\mathbb{N}^*$`, `$u_n ${incr?'>':'<'} ${a}$ với mọi $n \\in \\mathbb{N}^*$`, ()=>{ for(let n=1;n<300;n++){ if(incr ? !(u(n)<a) : !(u(n)>a)) return false; } return true; }, ()=>{ for(let n=1;n<300;n++){ if(incr ? !(u(n)>a) : !(u(n)<a)) return false; } return true; })
  ];
  return {stem:`Cho dãy số $(u_n)$ với $u_n = \\dfrac{${termsT([[a,'n'],[b,'']])}}{n + ${c}}$.`, items,
    lg:`$u_n = ${a} + \\dfrac{${b-a*c}}{n + ${c}}$; vì $${b-a*c} ${b-a*c<0?'< 0':'> 0'}$ nên dãy ${incr?'tăng':'giảm'} và $u_n ${incr?'<':'>'} ${a}$; $u_1 = ${frT(a+b,1+c)}$, $u_{${k}} = ${frT(a*k+b,k+c)}$.`};
});
// ---------- Cấp số cộng ----------
G(11,1,1,'TH','Tìm công sai, số hạng đầu của cấp số cộng', R=>{
  const u1 = R.int(-10,10), d = R.nz(-6,6), [m,n] = R.distinct(2,2,10).sort((x,y)=>x-y);
  const um = u1+(m-1)*d, un = u1+(n-1)*d, ask = R.pick(['d','u1']);
  const val = ask==='d' ? d : u1;
  return {stem:`Cho cấp số cộng $(u_n)$ có $u_{${m}} = ${um}$ và $u_{${n}} = ${un}$. ${ask==='d'?'Công sai $d$':'Số hạng đầu $u_1$'} của cấp số cộng bằng`,
    ans:T0(val), wrong: ask==='d' ? [T0(-d), T0((un-um)/(n-m+1)), T0(un-um), T0(d+1)] : [T0(um-m*d), T0(u1+d), T0(-u1===u1?u1+2:-u1), T0(um)],
    lg:`$u_{${n}} - u_{${m}} = ${n-m}d \\Rightarrow d = \\dfrac{${un} - (${um})}{${n-m}} = ${d}$; $u_1 = u_{${m}} - ${m-1}d = ${u1}$.`,
    verify:()=>{ const s=[u1]; for(let i=1;i<n;i++) s.push(s[i-1]+d); return s[m-1]===um && s[n-1]===un && val===(ask==='d'?s[1]-s[0]:s[0]); }};
});
G(11,1,1,'NB','Ba số lập thành cấp số cộng', R=>{
  const y = R.int(-10,10), d = R.nz(-8,8), z = y+d, x = y-d;
  return {stem:`Biết ba số $x;\\ ${y};\\ ${z}$ theo thứ tự lập thành một cấp số cộng. Giá trị của $x$ là`,
    ans:T0(x), wrong:[T0(2*z-y), T0(y+z), T0((y+z)/2), T0(-x===x?x+1:-x)],
    lg:`Ba số lập thành cấp số cộng khi số ở giữa bằng trung bình cộng hai số bên: $2\\cdot ${y} = x + ${z} \\Rightarrow x = ${x}$.`,
    verify:()=> y-x===z-y};
});
GT(11,1,1,'VD','Bài toán thực tế về cấp số cộng', R=>{
  const a = R.int(10,30), d = R.int(1,4), n = R.int(8,25);
  const S = n*(2*a+(n-1)*d)/2;
  if(S>9999) return null;
  return {stem:`Một hội trường có ${n} dãy ghế. Dãy thứ nhất có ${a} ghế, mỗi dãy sau nhiều hơn dãy liền trước ${d} ghế. Hỏi hội trường có tất cả bao nhiêu ghế?`, ans:S,
    lg:`Số ghế các dãy lập thành cấp số cộng với $u_1 = ${a}$, $d = ${d}$. Tổng số ghế $S_{${n}} = \\dfrac{${n}\\left[2\\cdot ${a} + ${n-1}\\cdot ${d}\\right]}{2} = ${S}$.`,
    verify:()=>{ let s=0, t=a; for(let i=0;i<n;i++){ s+=t; t+=d; } return s===S; }};
});
GD(11,1,1,'TH','Cấp số cộng: số hạng, tổng, tính chất', R=>{
  const u1 = R.int(-9,9), d = R.nz(-5,5), k = R.int(5,15), n = R.int(6,20);
  const seq = N=>{ const s=[]; let t=u1; for(let i=0;i<N;i++){ s.push(t); t+=d; } return s; };
  const uk = u1+(k-1)*d, Sn = n*(2*u1+(n-1)*d)/2;
  const mTrue = u1 + R.int(3,30)*d, mFalse = mTrue + (Math.abs(d)>1 ? 1 : 0.5);
  const items = [
    claimN(R, v=>`$u_{${k}} = ${v}$`, uk, String(uk), u1+k*d, String(u1+k*d), ()=> seq(k)[k-1]),
    claimN(R, v=>`Tổng ${n} số hạng đầu $S_{${n}} = ${v}$`, Sn, String(Sn), n*(u1+(n-1)*d), String(n*(u1+(n-1)*d)), ()=> seq(n).reduce((s,x)=>s+x,0)),
    claim(R, `Số $${mTrue}$ là một số hạng của cấp số cộng`, `Số $${nt(mFalse)}$ là một số hạng của cấp số cộng`, ()=> seq(400).includes(mTrue), ()=> seq(400).some(x=>near(x,mFalse,1e-12))),
    claim(R, `Cấp số cộng là dãy số ${d>0?'tăng':'giảm'}`, `Cấp số cộng là dãy số ${d>0?'giảm':'tăng'}`, ()=>{ const s=seq(20); return s.every((x,i)=> i===0 || (d>0 ? x>s[i-1] : x<s[i-1])); }, ()=>{ const s=seq(20); return s.every((x,i)=> i===0 || (d>0 ? x<s[i-1] : x>s[i-1])); })
  ];
  return {stem:`Cho cấp số cộng $(u_n)$ có $u_1 = ${u1}$ và công sai $d = ${d}$.`, items,
    lg:`$u_n = ${u1} ${d<0?'-':'+'} ${Math.abs(d)}(n - 1)$; $u_{${k}} = ${uk}$; $S_{${n}} = \\dfrac{${n}(2u_1 + ${n-1}d)}{2} = ${Sn}$; số $m$ là số hạng khi $\\dfrac{m - u_1}{d} + 1$ là số nguyên dương; $d ${d>0?'> 0':'< 0'}$ nên dãy ${d>0?'tăng':'giảm'}.`};
});
