/* ===== Dạng đọc bảng biến thiên (bảng lập từ hàm số ẩn, app tự vẽ bằng tkz-tab) ===== */
const plainPoly = co=>{ // [hệ số bậc cao → thấp] → "x^3-3x^2+2" (dạng app đọc được để đối chiếu)
  const d = co.length-1; let s = '';
  co.forEach((c,i)=>{ const p = d-i; if(!c) return; const a = Math.abs(c), sg = c<0 ? '-' : (s ? '+' : '');
    s += sg + (p===0 ? a : (a===1 ? '' : a+'*')) + (p===0 ? '' : p===1 ? 'x' : 'x^'+p); });
  return s || '0';
};
const polyEval = (co, x)=> co.reduce((s,c)=> s*x + c, 0);
const bbtCell = v=> v===Infinity ? '+\\infty' : v===-Infinity ? '-\\infty' : (Number.isInteger(v) ? String(v) : frTex(v));
const frTex = v=>{ for(let q=1;q<=12;q++){ const p=Math.round(v*q); if(Math.abs(v-p/q)<1e-12) return frT(p,q); } return nt(v); };
function hiddenFunc(R, kind, small){
  // small: giá trị nhỏ (±6) cho câu đọc đồ thị — đồ thị gọn, gần gốc toạ độ như đề thi thật
  // Hàm số ẩn có điểm tới hạn nguyên, giá trị nguyên; trả về {co|rat, f, crit, bbt}
  if(kind==='cubic'){
    let r1, r2, s, d, co;
    for(let t=0; t<50; t++){   // giữ các giá trị cực trị trong khoảng ±40 cho gần với đề thi
      [r1,r2] = cubicCrit(R); s = R.sign(); d = small ? R.int(-3,3) : R.int(-6,6);
      co = [s, -3*s*(r1+r2)/2, 3*s*r1*r2, d];
      if(Math.max(Math.abs(polyEval(co,r1)), Math.abs(polyEval(co,r2))) <= (small ? 6 : 40) && (!small || Math.max(Math.abs(r1),Math.abs(r2)) <= 2)) break;
    }
    const f = x=> polyEval(co,x);
    const bbt = {loai:'bbt', nhan:['x',"f'(x)",'f(x)'], x:['-\\infty',String(r1),String(r2),'+\\infty'], dau: s>0?['+','-','+']:['-','+','-'], tai:['','0','0',''],
      y:[s>0?'-\\infty':'+\\infty', String(f(r1)), String(f(r2)), s>0?'+\\infty':'-\\infty'], hamSo: plainPoly(co)};
    return {kind, co, f, crit:[r1,r2], lead:s, bbt};
  }
  if(kind==='quartic'){
    const m = small ? 1 : R.int(1,3), s = R.sign(), c = small ? R.int(-3,3) : R.int(-6,6);
    const co = [s, 0, -2*s*m*m, 0, c];
    const f = x=> polyEval(co,x);
    const bbt = {loai:'bbt', nhan:['x',"f'(x)",'f(x)'], x:['-\\infty',String(-m),'0',String(m),'+\\infty'], dau: s>0?['-','+','-','+']:['+','-','+','-'], tai:['','0','0','0',''],
      y:[s>0?'+\\infty':'-\\infty', String(f(-m)), String(f(0)), String(f(m)), s>0?'+\\infty':'-\\infty'], hamSo: plainPoly(co)};
    return {kind, co, f, crit:[-m,0,m], lead:s, bbt};
  }
  // phân thức y = (a x + b)/(x + d)
  let a, b, d; do{ a = small ? R.nz(-3,3) : R.nz(-4,4); b = small ? R.int(-4,4) : R.int(-6,6); d = small ? R.nz(-3,3) : R.nz(-5,5); }while(a*d - b === 0);
  const f = x=> (a*x+b)/(x+d), inc = a*d-b > 0;
  const bbt = {loai:'bbt', nhan:['x',"f'(x)",'f(x)'], x:['-\\infty',String(-d),'+\\infty'], dau: inc?['+','+']:['-','-'], tai:['','||',''],
    y:[String(a), inc?'+\\infty | -\\infty':'-\\infty | +\\infty', String(a)], hamSo:`(${plainPoly([a,b])})/(${plainPoly([1,d])})`};
  return {kind, a, b, d, f, inc, bbt};
}
// kiểm tra độc lập bằng số: dấu đạo hàm trên khoảng, số nghiệm của f(x) = m
const dNum = (f,x)=> (f(x+1e-6)-f(x-1e-6))/2e-6;
const monoOn = (f, lo, hi, up)=>{ const A = isFinite(lo)?lo:hi-50, B = isFinite(hi)?hi:lo+50; for(let i=1;i<200;i++){ const x = A+(B-A)*i/200; const v = dNum(f,x); if(up ? !(v>0) : !(v<0)) return false; } return true; };
const countSol = (f, m)=> findRealRoots(x=> f(x)-m, -40, 40, 0.004).length;
const ivStr = (lo, hi)=> `$(${bbtCell(lo)}; ${bbtCell(hi)})$`;
const BBT_STEM = 'Cho hàm số $y = f(x)$ có bảng biến thiên như sau:';
G(12,0,0,'NB','Đọc khoảng đơn điệu từ bảng biến thiên', R=>{
  const H = hiddenFunc(R, R.pick(['cubic','cubic','quartic']));
  const xs = [-Infinity, ...H.crit, Infinity];
  const iv = xs.slice(0,-1).map((lo,i)=>({lo, hi:xs[i+1], up:H.bbt.dau[i]==='+'}));
  const up = R.rnd()<0.5;
  const good = R.pick(iv.filter(v=> v.up===up)), bad = iv.filter(v=> v.up!==up);
  const vals = H.crit.map(H.f).sort((p,q)=>p-q);
  const wrong = [...bad.map(v=>({t:ivStr(v.lo,v.hi), v:'b'+v.lo})),
    {t:ivStr(H.crit[0]-1, H.crit[H.crit.length-1]+1), v:'span'},
    {t:ivStr(vals[0], vals[vals.length-1]), v:'yval'}];
  return {stem:`${BBT_STEM} Hàm số đã cho ${up?'đồng biến':'nghịch biến'} trên khoảng nào dưới đây?`, hv:H.bbt,
    ans:{t:ivStr(good.lo, good.hi), v:'g'}, wrong,
    lg:`Trên khoảng ${ivStr(good.lo, good.hi)} ta có $f'(x) ${up?'>':'<'} 0$ nên hàm số ${up?'đồng biến':'nghịch biến'}. Lưu ý khoảng đơn điệu đọc theo hàng $x$, không đọc theo giá trị của $f(x)$.`,
    verify:()=> monoOn(H.f, good.lo, good.hi, up) && !monoOn(H.f, H.crit[0]-1, H.crit[H.crit.length-1]+1, up) && bad.every(v=> !monoOn(H.f, v.lo, v.hi, up))};
});
G(12,0,0,'TH','Đọc cực trị từ bảng biến thiên', R=>{
  const H = hiddenFunc(R, R.pick(['cubic','quartic']));
  const ask = R.pick(['yCD','yCT','xCD','xCT']);
  // điểm cực đại: f' đổi dấu + → −
  const isMax = x=> dNum(H.f, x-0.01) > 0 && dNum(H.f, x+0.01) < 0, isMin = x=> dNum(H.f, x-0.01) < 0 && dNum(H.f, x+0.01) > 0;
  const want = ask.endsWith('CD') ? H.crit.filter(isMax) : H.crit.filter(isMin);
  const other = ask.endsWith('CD') ? H.crit.filter(isMin) : H.crit.filter(isMax);
  if(want.length!==1) return null;             // hỏi "giá trị cực đại" khi có đúng 1 điểm cực đại
  const x0 = want[0], y0 = H.f(x0), x1 = other[0], y1 = H.f(x1);
  const isY = ask[0]==='y';
  const val = isY ? y0 : x0;
  const wrong = [isY ? x0 : y0, isY ? y1 : x1, isY ? x1 : y1, val+ (val>0?-1:1)*2].map(T0);
  return {stem:`${BBT_STEM} ${isY ? `Giá trị ${ask.endsWith('CD')?'cực đại':'cực tiểu'} của hàm số đã cho bằng` : `Điểm ${ask.endsWith('CD')?'cực đại':'cực tiểu'} của hàm số đã cho là`}`, hv:H.bbt,
    ans:T0(val), wrong,
    lg:`$f'(x)$ đổi dấu từ ${ask.endsWith('CD')?'$+$ sang $-$':'$-$ sang $+$'} khi đi qua $x = ${x0}$ nên hàm số đạt ${ask.endsWith('CD')?'cực đại':'cực tiểu'} tại $x = ${x0}$, giá trị ${ask.endsWith('CD')?'cực đại':'cực tiểu'} bằng $f(${x0}) = ${y0}$.`,
    verify:()=> (ask.endsWith('CD') ? isMax(x0) : isMin(x0)) && near(H.f(x0), y0) && near(val, isY ? H.f(x0) : x0)};
});
G(12,0,2,'NB','Đọc tiệm cận từ bảng biến thiên', R=>{
  const H = hiddenFunc(R, 'rat');
  const ask = R.pick(['dung','ngang']);
  const E = (c, v)=> ({t:`$${c} = ${v}$`, v:c+v});
  const ans = ask==='dung' ? E('x', -H.d) : E('y', H.a);
  const wrong = ask==='dung' ? [E('y', -H.d), E('x', H.a), E('y', H.a)] : [E('x', H.a), E('y', -H.d), E('x', -H.d)];
  return {stem:`${BBT_STEM} Đường tiệm cận ${ask==='dung'?'đứng':'ngang'} của đồ thị hàm số đã cho là`, hv:H.bbt, ans, wrong,
    lg: ask==='dung' ? `Vì $\\lim\\limits_{x \\to (${-H.d})^{-}} f(x)$ và $\\lim\\limits_{x \\to (${-H.d})^{+}} f(x)$ là vô cực nên $x = ${-H.d}$ là tiệm cận đứng.` : `Vì $\\lim\\limits_{x \\to \\pm\\infty} f(x) = ${H.a}$ nên $y = ${H.a}$ là tiệm cận ngang.`,
    verify:()=> ask==='dung' ? (Math.abs(H.f(-H.d+1e-9))>1e6 && Math.abs(H.f(-H.d-1e-9))>1e6) : near(H.f(1e9), H.a, 1e-6)};
});
GT(12,0,3,'TH','Số nghiệm của phương trình f(x) = m (đọc bảng biến thiên)', R=>{
  const H = hiddenFunc(R, R.pick(['cubic','quartic']));
  const vals = [...new Set(H.crit.map(H.f))].sort((p,q)=>p-q);
  // m: đúng bằng một cực trị, nằm giữa, hoặc nằm ngoài
  const cand = [...vals, vals[0]-R.int(1,3), vals[vals.length-1]+R.int(1,3)];
  for(let i=0;i<vals.length-1;i++) if(vals[i+1]-vals[i]>=2) cand.push(vals[i]+1);
  const m = R.pick(cand), k = R.pick([1,2,3]), c = k*m;   // phương trình k·f(x) - c = 0
  const cnt = countSol(H.f, m);
  return {stem:`${BBT_STEM} Phương trình $${k===1?'':k}f(x) ${c<0?'+':'-'} ${Math.abs(c)} = 0$ có bao nhiêu nghiệm thực?`, hv:H.bbt, ans:cnt,
    lg:`Phương trình tương đương $f(x) = ${m}$. Số nghiệm bằng số giao điểm của đồ thị $y = f(x)$ với đường thẳng $y = ${m}$; dựa vào bảng biến thiên ta được $${cnt}$ nghiệm.`,
    verify:()=>{ // đếm độc lập theo bảng: số khoảng đơn điệu có miền giá trị chứa m (tính cả chạm tại điểm cực trị)
      const xs = [-Infinity, ...H.crit, Infinity]; let n = 0;
      for(let i=0;i<xs.length-1;i++){ const lo = isFinite(xs[i]) ? H.f(xs[i]) : (H.bbt.y[0].includes('-') ? -Infinity : Infinity), hi = isFinite(xs[i+1]) ? H.f(xs[i+1]) : (H.bbt.y[H.bbt.y.length-1].includes('-') ? -Infinity : Infinity);
        const a = Math.min(lo,hi), b = Math.max(lo,hi);
        if(m > a && m < b) n++; }
      H.crit.forEach(x=>{ if(near(H.f(x), m, 1e-12)) n++; });
      return n===cnt; }};
});
GD(12,0,0,'TH','Bảng biến thiên: đơn điệu, cực trị, số nghiệm', R=>{
  const H = hiddenFunc(R, 'cubic');
  const [r1, r2] = H.crit, f1 = H.f(r1), f2 = H.f(r2), s = H.lead;
  const yCD = s>0 ? f1 : f2, yCT = s>0 ? f2 : f1, xCD = s>0 ? r1 : r2;
  const mid = (f1+f2)/2;
  const items = [
    claim(R, `Hàm số ${s>0?'nghịch biến':'đồng biến'} trên khoảng $(${r1}; ${r2})$`, `Hàm số ${s>0?'đồng biến':'nghịch biến'} trên khoảng $(${r1}; ${r2})$`, ()=> monoOn(H.f, r1, r2, s<0), ()=> monoOn(H.f, r1, r2, s>0)),
    claimN(R, v=>`Giá trị cực đại của hàm số bằng $${v}$`, yCD, String(yCD), xCD, String(xCD), ()=>{ const x = [r1,r2].find(x=> dNum(H.f,x-0.01)>0 && dNum(H.f,x+0.01)<0); return H.f(x); }),
    claimN(R, v=>`Phương trình $f(x) = ${frTex(mid)}$ có $${v}$ nghiệm thực phân biệt`, 3, '3', 2, '2', ()=> countSol(H.f, mid)),
    claimN(R, v=>`Phương trình $f(x) = ${yCT}$ có $${v}$ nghiệm thực phân biệt`, 2, '2', 3, '3', ()=> countSol(H.f, yCT))
  ];
  return {stem:BBT_STEM, hv:H.bbt, items,
    lg:`Từ bảng biến thiên: hàm số ${s>0?'đồng biến':'nghịch biến'} trên $(-\\infty; ${r1})$ và $(${r2}; +\\infty)$, ${s>0?'nghịch biến':'đồng biến'} trên $(${r1}; ${r2})$; $y_{CĐ} = ${yCD}$, $y_{CT} = ${yCT}$. Đường thẳng $y = m$ với $${Math.min(f1,f2)} < m < ${Math.max(f1,f2)}$ cắt đồ thị tại 3 điểm; $y = ${yCT}$ tiếp xúc tại điểm cực tiểu nên cắt tại 2 điểm.`};
});

/* ===== Dạng đọc đồ thị (đồ thị vẽ từ hàm số ẩn, app tự căn khung) ===== */
const GRAPH_STEM = 'Cho hàm số $y = f(x)$ có đồ thị như hình vẽ dưới đây.';
const graphHv = (hamSo, extra)=> Object.assign({loai:'dothi', hamSo}, extra||{});
// phương án nhiễu phải khác đồ thị thật rõ rệt trong khung hình (để học sinh phân biệt được bằng mắt)
const visiblyDiff = (hv, g)=>{ const M = graphModel(hv); if(!M.ok) return false; const f = M.A.f;
  for(let i=0;i<=60;i++){ const x = M.xmin + (M.xmax-M.xmin)*i/60; const a = f(x), b = g(x); if(isFinite(a) && a>=M.ymin && a<=M.ymax && (!isFinite(b) || Math.abs(a-b) > 0.4)) return true; } return false; };
const ratTex = (a,b,d)=> `\\dfrac{${termsT([[a,'x'],[b,'']])}}{${termsT([[1,'x'],[d,'']])}}`;
G(12,0,3,'TH','Nhận dạng hàm số từ đồ thị', R=>{
  const H = hiddenFunc(R, R.pick(['cubic','cubic','quartic','rat']), true);
  const hv = graphHv(H.bbt.hamSo);
  let ans, cands;
  if(H.kind==='rat'){
    const {a,b,d} = H;
    const mk = (A,B,D)=> ({t:`$y = ${ratTex(A,B,D)}$`, v:`${A},${B},${D}`, g:x=> (A*x+B)/(x+D)});
    ans = mk(a,b,d);
    cands = [mk(a,b,-d), mk(-a,b,d), mk(a,-b,d), mk(a,b+2*d,d), mk(-a,-b,-d)];
  } else {
    const co = H.co;
    const mk = c=> ({t:`$y = ${polyT(c)}$`, v:c.join(','), g:x=> polyEval(c,x)});
    ans = mk(co);
    const flip = co.map(v=>-v), shift = co.map((v,i)=> i===co.length-1 ? v+2 : v), shift2 = co.map((v,i)=> i===co.length-1 ? v-2 : v);
    const mirror = co.map((v,i)=> (co.length-1-i)%2 ? -v : v);   // f(-x)
    cands = [mk(flip), mk(shift), mk(shift2), mk(mirror)];
  }
  const wrong = cands.filter(c=> c.v!==ans.v && visiblyDiff(hv, c.g));
  if(wrong.length < 3) return null;
  return {stem:`Đường cong trong hình vẽ dưới đây là đồ thị của hàm số nào?`, hv, ans:{t:ans.t, v:ans.v}, wrong:wrong.map(c=>({t:c.t, v:c.v})),
    lg: H.kind==='rat' ? `Đồ thị có tiệm cận đứng $x = ${-H.d}$, tiệm cận ngang $y = ${H.a}$ và cắt trục tung tại điểm có tung độ ${frT(H.b,H.d)}; chỉ hàm số ${ans.t} thoả mãn.`
      : `Dựa vào dáng đồ thị (dấu hệ số bậc cao nhất), các điểm cực trị và giao điểm với trục tung, chỉ hàm số ${ans.t} thoả mãn.`,
    verify:()=>{ const M = graphModel(hv); return M.ok && [0.3,1.1,-1.7,2.4].every(x=>{ const a = M.A.f(x), b = ans && H.f(x); return !isFinite(a) || Math.abs(a-b) < 1e-9; }) && wrong.every(c=> visiblyDiff(hv, c.g)); }};
});
