G(10,4,2,'TH','Phương sai, độ lệch chuẩn', R=>{
  const data = c10Nice(R); if(!data) return null;
  const ask = R.pick(['var','std']);
  const v = c10Var(data), sd = Math.sqrt(v);
  const tex = x=>{ // phương sai: phân số; độ lệch chuẩn: căn
    if(ask==='var') return c10Frac(Math.round(x*1e9)/1e9);
    const q = Math.round(x*x*4); if(Math.abs(x*x*4 - q) > 1e-6) return nt(Math.round(x*100)/100);
    return q%4===0 ? sqT(q/4) : `\\dfrac{${sqT(q)}}{2}`;
  };
  const vSample = v*data.length/(data.length-1);
  const cand = ask==='var' ? [v, sd, vSample, v*2, v+1] : [sd, v, Math.sqrt(vSample), sd*2, Math.sqrt(v+1)];
  const u = cand.map(x=> ({x, t:tex(x)})).filter((c,i,arr)=> arr.findIndex(d=> d.t===c.t)===i);
  if(u.length<4 || u[0].x!==cand[0]) return null;
  return {stem:`Cho mẫu số liệu: ${c10DataT(data)}. ${ask==='var'?'Phương sai':'Độ lệch chuẩn'} của mẫu số liệu trên bằng`, ans:{t:`$${u[0].t}$`, v:'a'}, wrong:u.slice(1,4).map((c,i)=>({t:`$${c.t}$`, v:'w'+i})),
    lg:`$\\overline{x} = ${nt(c10Mean(data))}$; $s^2 = \\dfrac{1}{${data.length}}\\sum (x_i - \\overline{x})^2 = ${tex(v).replace(/\\dfrac/,'\\dfrac')}$${ask==='std'?`; $s = \\sqrt{s^2} = ${tex(sd)}$`:''}.`,
    verify:()=> Math.abs(c10VarCheck(data) - v) < 1e-9 && Math.abs((ask==='var'? v : sd) - cand[0]) < 1e-12};
});
