    const P1 = [R.int(-3, 3), R.int(-3, 3), R.int(-3, 3)], u1 = [R.nz(-2, 2), R.nz(-2, 2), R.nz(-2, 2)], P2 = [R.int(-3, 3), R.int(-3, 3), R.int(-3, 3)], u2 = [R.nz(-2, 2), R.nz(-2, 2), R.nz(-2, 2)];
