G(12,0,3,'TH','Nhận dạng hàm số từ bảng biến thiên (bậc ba, trùng phương)', R=>{
  for(let g = 0; g < 60; g++){ const H = hiddenFunc(R, R.pick(['cubic', 'cubic', 'quartic']), true), co = H.co, f = x=> pv(co, x), mk = C=> ({t:`$y = ${polyT(C)}$`, v:C.join(','), C});
    const ans = mk(co), n = co.length, cands = [mk(co.map(c=> -c)), mk(co.map((c, i)=> i === n - 1 ? c + 2 : c)), mk(co.map((c, i)=> i === n - 2 ? -c : c)), mk(co.map((c, i)=> i === 1 ? -c : c)), mk(co.map((c, i)=> i === n - 1 ? -c : c)), mk(co.map((c, i)=> i === 0 ? -c : c))];
    const sameBbt = C=>{ const g2 = x=> pv(C, x), ch = []; for(let x = -8.00037; x < 8; x += 0.001) if(dv(g2, x)*dv(g2, x + 0.001) < 0) ch.push(Math.round(x)); return ch.length === H.crit.length && ch.every((x, i)=> x === H.crit[i] && Math.abs(g2(x) - f(x)) < 1e-9) && Math.sign(C[0]) === Math.sign(co[0]); };
    const wrong = pk(ans, cands.filter(o=> !sameBbt(o.C))); if(!wrong) continue;
    return {stem:'Bảng biến thiên dưới đây là của hàm số nào trong các hàm số sau?', hv:H.bbt, ans, wrong,
      lg:`Từ bảng biến thiên: hàm số đạt cực trị tại $x = ${H.crit.join('$, $x = ')}$ với các giá trị $${H.crit.map(f).join('$, $')}$; khi $x \\to +\\infty$ thì $y \\to ${co[0] > 0 ? '+' : '-'}\\infty$ (hệ số bậc cao nhất ${co[0] > 0 ? 'dương' : 'âm'}).<br>Kiểm tra phương án $y = ${polyT(co)}$: $y' = ${polyT(co.slice(0, -1).map((c, i)=> c*(n - 1 - i)))}$ có nghiệm $x = ${H.crit.join('$, $x = ')}$ và ${H.crit.map(x=> `$y(${x}) = ${f(x)}$`).join(', ')} — khớp bảng. Các phương án còn lại sai dấu hệ số bậc cao, sai điểm cực trị hoặc sai giá trị cực trị.`,
      verify:()=> sameBbt(co) && wrong.every(w=> !sameBbt(w.C))}; }
  return null;
});
G(12,0,3,'VD','Nhận dạng đồ thị hàm phân thức bậc hai trên bậc nhất (có tiệm cận xiên)', R=>{
  for(let g = 0; g < 80; g++){ const a = R.pick([1, -1, 2, -2]), d = R.nz(-2, 2), q = R.int(-2, 2), rr = a*R.pick([1, 4]);   // rr = a·t²: hai cực trị tại x = −d ± t (toạ độ nguyên, đồ thị gọn)   // y = ax + q + rr/(x + d)·… viết dạng (ax² + Bx + C)/(x + d)
    const B = a*d + q, C = q*d + rr, mk = (A, Bb, Cc, D)=> ({t:`$y = \\dfrac{${termsT([[A, 'x^2'], [Bb, 'x'], [Cc, '']])}}{${termsT([[1, 'x'], [D, '']])}}$`, v:[A, Bb, Cc, D].join(','), g:x=> (A*x*x + Bb*x + Cc)/(x + D)});
    const ans = mk(a, B, C, d), hv = graphHv(`(${plainPoly([a, B, C])})/(${plainPoly([1, d])})`), cands = [mk(-a, -B, -C, d), mk(a, B, C, -d), mk(a, -B, C, -d), mk(a, B + 2*a, C, d), mk(a, B, -C, d)];
    const wrong = pk(ans, cands.filter(o=> visiblyDiff(hv, o.g))); if(!wrong) continue;
    return {stem:'Đường cong trong hình dưới đây là đồ thị của hàm số nào?', hv, ans, wrong,
      lg:`Từ đồ thị: tiệm cận đứng $x = ${-d}$ (mẫu là $${termsT([[1, 'x'], [d, '']])}$), tiệm cận xiên có hệ số góc ${a > 0 ? 'dương' : 'âm'}.<br>$\\dfrac{${termsT([[a, 'x^2'], [B, 'x'], [C, '']])}}{${termsT([[1, 'x'], [d, '']])}} = ${termsT([[a, 'x'], [q, '']])} ${rr < 0 ? '-' : '+'} \\dfrac{${Math.abs(rr)}}{${termsT([[1, 'x'], [d, '']])}}$: tiệm cận xiên $y = ${termsT([[a, 'x'], [q, '']])}$, đồ thị ${rr*1 > 0 ? 'nằm phía trên' : 'nằm phía dưới'} tiệm cận xiên khi $x > ${-d}$ — khớp hình vẽ. Các phương án khác sai tiệm cận đứng, sai hướng tiệm cận xiên hoặc sai vị trí nhánh.`,
      verify:()=> wrong.every(w=> visiblyDiff(hv, w.g)) && Math.abs(ans.g(1e4) - (a*1e4 + q)) < 1e-2}; }
  return null;
});
GD(12,0,3,'VD','Hàm phân thức bậc hai trên bậc nhất (đúng – sai): khoảng cách hai điểm cực trị, giới hạn, giao điểm với đường thẳng, tiệm cận xiên', R=>{
  for(let g = 0; g < 60; g++){ const t = R.int(1, 3), d = R.int(-2, 2), p = R.int(-3, 3), sg = R.pick([1, -1]), B = 2*d + p, C = d*d + d*p + sg*t*t;   // y = x + (p + d) + sg·t²/(x + d) − d?  viết: y = x + p + sg t²/(x + d) ⇒ tử = x² + (d + p)x + (dp + sg t²)
    const B2 = d + p, C2 = d*p + sg*t*t, f = x=> (x*x + B2*x + C2)/(x + d), T = `\\dfrac{${termsT([[1, 'x^2'], [B2, 'x'], [C2, '']])}}{${termsT([[1, 'x'], [d, '']])}}`;
    const hasExt = sg > 0, dist = hasExt ? 2*t : 0;   // cực trị tại x = −d ± t, khoảng cách = 2t√5
    const kL = R.int(-3, 3), mL = R.int(-4, 4), nInt = (()=>{ const A = 1 - kL, Bq = A*d + (p - mL), Cq = (p - mL)*d + t*t; let rts = []; if(A === 0){ if(Bq !== 0) rts = [-Cq/Bq]; } else { const D = Bq*Bq - 4*A*Cq; if(D > 1e-12) rts = [(-Bq - Math.sqrt(D))/(2*A), (-Bq + Math.sqrt(D))/(2*A)]; else if(Math.abs(D) <= 1e-12) rts = [-Bq/(2*A)]; } return rts.filter(x=> Math.abs(x + d) > 1e-9).length; })();   // ((1 − k)x + p − m)(x + d) + t² = 0
    if(!hasExt) continue; const lim = R.pick(['+', '-']), limV = lim === '+' ? '+\\infty' : '-\\infty';
    return {stem:`Cho hàm số $y = h(x) = ${T}$. Xét tính đúng sai của các mệnh đề sau:`,
      items:[claim(R, `Khoảng cách giữa hai điểm cực trị của đồ thị hàm số bằng $${t === 1 ? '' : 2*t}${t === 1 ? '2' : ''}\\sqrt{5}$`.replace('$2\\sqrt{5}$', '$2\\sqrt{5}$'), `Khoảng cách giữa hai điểm cực trị của đồ thị hàm số bằng $${4*t}$`, ()=> true, ()=> false),
        claim(R, `$\\lim\\limits_{x \\to ${-d}^{${lim}}} h(x) = ${(lim === '+') === (sg > 0) ? '+\\infty' : '-\\infty'}$`, `$\\lim\\limits_{x \\to ${-d}^{${lim}}} h(x) = ${(lim === '+') === (sg > 0) ? '-\\infty' : '+\\infty'}$`, ()=> true, ()=> false),
        claimN(R, v=> `Đồ thị hàm số $y = h(x)$ và đường thẳng $y = ${termsT([[kL, 'x'], [mL, '']])}$ có $${v}$ điểm chung`, nInt, String(nInt), nInt === 2 ? 1 : nInt + 1, String(nInt === 2 ? 1 : nInt + 1), ()=>{ let c = 0; const G = x=> f(x) - kL*x - mL; for(let x = -80.0003; x < 80; x += 0.0004){ if(Math.abs(x + d) < 0.002 || Math.abs(x + 0.0004 + d) < 0.002 || (x + d)*(x + 0.0004 + d) < 0) continue; if(G(x)*G(x + 0.0004) < 0) c++; } for(const z of [-d - t, -d + t]) if(Math.abs(G(z)) < 1e-9 && Math.sign(G(z - 0.01)) === Math.sign(G(z + 0.01))) c++; return c; }),
        claim(R, `Đồ thị hàm số có tiệm cận xiên là đường thẳng $y = ${termsT([[1, 'x'], [p, '']])}$`, `Đồ thị hàm số có tiệm cận xiên là đường thẳng $y = ${termsT([[1, 'x'], [p + (d === 0 ? 1 : 2*d), '']])}$`, ()=> true, ()=> false)],
      lg:`Viết $h(x) = ${termsT([[1, 'x'], [p, '']])} + \\dfrac{${t*t}}{${termsT([[1, 'x'], [d, '']])}}$.<br>a) $h'(x) = 1 - \\dfrac{${t*t}}{(${termsT([[1, 'x'], [d, '']])})^2} = 0 \\Leftrightarrow x = ${-d - t}$ hoặc $x = ${-d + t}$; hai điểm cực trị $(${-d - t}; ${f(-d - t)})$ và $(${-d + t}; ${f(-d + t)})$, khoảng cách $\\sqrt{${2*t}^2 + ${4*t}^2} = ${2*t}\\sqrt{5}$.<br>b) Khi $x \\to ${-d}^{${lim}}$: $\\dfrac{${t*t}}{${termsT([[1, 'x'], [d, '']])}} \\to ${lim === '+' ? '+\\infty' : '-\\infty'}$ nên $h(x) \\to ${lim === '+' ? '+\\infty' : '-\\infty'}$.<br>c) Phương trình hoành độ giao điểm $h(x) = ${termsT([[kL, 'x'], [mL, '']])}$ (với $x \\ne ${-d}$) có $${nInt}$ nghiệm.<br>d) $\\lim\\limits_{x \\to \\pm\\infty}[h(x) - (${termsT([[1, 'x'], [p, '']])})] = 0$ nên tiệm cận xiên là $y = ${termsT([[1, 'x'], [p, '']])}$.`,
      verify:()=>{ const e = []; for(let x = -20.00037; x < 20; x += 0.001){ if(Math.abs(x + d) < 0.01) continue; if(dv(f, x)*dv(f, x + 0.001) < 0) e.push(x); } if(e.length !== 2) return false; const [u, v] = e; return Math.abs(Math.hypot(v - u, f(v) - f(u)) - 2*t*Math.sqrt(5)) < 0.01 && Math.abs(f(1e5) - (1e5 + p)) < 1e-3 && (lim === '+' ? f(-d + 1e-6) > 1e4 : f(-d - 1e-6) < -1e4); }}; }
  return null;
});
GD(12,0,3,'TH','Hàm bậc ba (đúng – sai): đạo hàm, hai điểm cực trị nằm hai phía trục tung, GTLN trên đoạn, hệ số góc đường thẳng đi qua hai điểm cực trị', R=>{
  for(let g = 0; g < 60; g++){ const [x1, x2] = R.distinct(2, -3, 4).sort((a, b)=> a - b); if((x1 + x2) % 2) continue; const b = -3*(x1 + x2)/2, c = 3*x1*x2, d = R.int(-4, 4), co = [1, b, c, d], f = x=> pv(co, x);
    if(x1*x2 === 0) continue; const A = R.int(-1, 0), Bd = R.int(Math.max(x2, 1) + 1, Math.max(x2, 1) + 3), vals = [A, Bd, x1, x2].filter(x=> x >= A && x <= Bd).map(f), M = Math.max(...vals), k = (f(x2) - f(x1))/(x2 - x1), opp = x1*x2 < 0;
    if(!Number.isInteger(k) || Math.abs(M) > 200) continue;
    return {stem:`Cho hàm số $y = f(x) = ${polyT(co)}$. Xét tính đúng sai của các mệnh đề sau:`,
      items:[claim(R, `Hàm số có đạo hàm $f'(x) = ${polyT([3, 2*b, c])}$`, `Hàm số có đạo hàm $f'(x) = ${b ? polyT([3, b, c]) : polyT([3, 0, 3*c])}$`, ()=> true, ()=> false),
        claim(R, opp ? `Đồ thị hàm số có hai điểm cực trị nằm về hai phía của trục tung` : `Đồ thị hàm số có hai điểm cực trị nằm cùng một phía đối với trục tung`, opp ? `Đồ thị hàm số có hai điểm cực trị nằm cùng một phía đối với trục tung` : `Đồ thị hàm số có hai điểm cực trị nằm về hai phía của trục tung`, ()=> opp ? x1*x2 < 0 : x1*x2 > 0, ()=> opp ? x1*x2 > 0 : x1*x2 < 0),
        claimN(R, v=> `Giá trị lớn nhất của hàm số trên đoạn $[${A}; ${Bd}]$ bằng $${v}$`, M, String(M), Math.max(f(x1), f(x2)) === M ? f(Bd) : Math.max(f(x1), f(x2)), String(Math.max(f(x1), f(x2)) === M ? f(Bd) : Math.max(f(x1), f(x2))), ()=>{ let m = -Infinity; for(let x = A; x <= Bd + 1e-9; x += 0.001) m = Math.max(m, f(x)); return Math.round(m*1e6)/1e6; }),
        claimN(R, v=> `Đường thẳng đi qua hai điểm cực trị của đồ thị hàm số có hệ số góc $k = ${v}$`, k, String(k), -k === k ? k + 1 : -k, String(-k === k ? k + 1 : -k), ()=> k)],
      lg:`a) $f'(x) = ${polyT([3, 2*b, c])}$.<br>b) $f'(x) = 0 \\Leftrightarrow x = ${x1}$ hoặc $x = ${x2}$; ${opp ? 'hai hoành độ trái dấu nên hai điểm cực trị nằm về hai phía trục tung' : x1*x2 === 0 ? 'một điểm cực trị nằm trên trục tung' : 'hai hoành độ cùng dấu nên hai điểm cực trị nằm cùng một phía trục tung'}.<br>c) Trên $[${A}; ${Bd}]$: ${[...new Set([A, x1, x2, Bd])].filter(x=> x >= A && x <= Bd).sort((u, v)=> u - v).map(x=> `$f(${x}) = ${f(x)}$`).join(', ')}; giá trị lớn nhất là $${M}$.<br>d) Hai điểm cực trị $(${x1}; ${f(x1)})$, $(${x2}; ${f(x2)})$; hệ số góc $k = \\dfrac{${f(x2)} - ${par(f(x1))}}{${x2} - ${par(x1)}} = ${k}$.`}; }
  return null;
});

