  if(nbBad >= 2) tips.push(['📚', 'Ôn lại định nghĩa, công thức của bài: các câu nhận biết – thông hiểu là điểm “dễ ăn” nhất, đừng để mất.']);
  else if(vdBad && !nbBad) tips.push(['🧠', 'Kiến thức nền của em đã vững — luyện thêm vài bài vận dụng mỗi ngày để lên điểm cao.']);
  if(tln.length) tips.push(['🧮', `Trả lời ngắn: kiểm tra lại phép tính, cách làm tròn và cách tô dấu “−”, dấu phẩy (${cq(tln.map(q=> q.n))}).`]);
  if(blank.length) tips.push(['✏️', `Đừng bỏ trống: còn ${blank.length} câu chưa làm (${cq(blank.map(q=> q.n).slice(0, 4))}${blank.length > 4 ? '…' : ''}). Phân bổ thời gian, câu khó để sau nhưng nhớ quay lại.`]);
