  const D0 = new Date(), today = D0.getFullYear() + '-' + String(D0.getMonth()+1).padStart(2,'0') + '-' + String(D0.getDate()).padStart(2,'0'), t = kind==='ws' ? list[0].rec : null; if(kind==='ws' && !t) return;
  const kinds = kind==='ws' ? ['Kiểm tra 15 phút','Kiểm tra thường xuyên','Kiểm tra 45 phút','Bài tập về nhà','Rèn luyện','Khảo sát','Khác'] : ['Giữa kỳ I','Cuối kỳ I','Giữa kỳ II','Cuối kỳ II','Khảo sát chất lượng','Thi thử','Khác'];
