  const defKind = kind==='ws' ? (list.length === 1 && list[0].s === 'home' ? 'Bài tập về nhà' : list.length === 1 && list[0].s === 'rl' ? 'Rèn luyện' : (last.wsKind || kinds[0])) : (kinds.find(k=> k.toLowerCase()===kl) || kinds[0]);
