      if(fs.some(f=> f < 0 || Math.abs(f - Math.round(f)) > 1e-9)) throw new Error('Tần số phải là số tự nhiên');
      const n = fs.reduce((s,f)=> s + Math.round(f), 0); if(!n) throw new Error('Tổng tần số bằng 0'); if(n > 20000) throw new Error('Cỡ mẫu quá lớn');
