      const sum = all.reduce((s,x)=> s + x, 0), mean = sum/n, sq = all.reduce((s,x)=> s + x*x, 0), ss = all.reduce((s,x)=> s + (x-mean)*(x-mean), 0);
      const med = arr=> arr.length % 2 ? arr[(arr.length-1)/2] : (arr[arr.length/2-1] + arr[arr.length/2])/2, half = Math.floor(n/2);
      const cnt = new Map(); all.forEach(x=> cnt.set(x, (cnt.get(x)||0) + 1)); const mxc = Math.max(...cnt.values()), modes = [...cnt].filter(e=> e[1]===mxc).map(e=> e[0]);
      const q1 = n > 1 ? med(all.slice(0, half)) : all[0], q3 = n > 1 ? med(all.slice(n - half)) : all[0];
      out.innerHTML = row('n =', calcShow(n)) + row('Trung bình x̄ =', calcShow(mean)) + row('Tổng Σx =', calcShow(sum)) + row('Σx² =', calcShow(sq))
