const CALC_FKEYS = [
  ['x⁻¹','i:^(-1)','x!','i:!'], ['▪⁄▫','i:/','%','i:%'], ['√▫','i:√():1','∛▫','i:∛():1'], ['x²','i:^2','x³','i:^3'], ['xⁿ','i:^():1','|x|','i:abs():1'], ['log','i:log():1','10ⁿ','i:10^():1'],
  ['ln','i:ln():1','eⁿ','i:e^():1'], ['(−)','i:−','x','i:x'], ['sin','i:sin():1','sin⁻¹','i:asin():1'], ['cos','i:cos():1','cos⁻¹','i:acos():1'], ['tan','i:tan():1','tan⁻¹','i:atan():1'], ['logₐb','i:log(;):2','Σ','i:Σ(;1;):4'],
  ['(','i:(','',''], [')','i:)','',''], ['S⇔D','SD','',''], ['nCr','i:C(;):2','nPr','i:P(;):2'], ['π','i:π','e','i:e'], [';','i:;','','']];
