  calcSetShift(false);
  if(cmd==='MENU'){ CALC.menu = !CALC.menu; CALC.pick = null; calcRender(); return; }
  if(cmd==='STO' || cmd==='VAR'){ const m = cmd==='STO' ? 'sto' : 'var'; CALC.pick = CALC.pick===m ? null : m; calcRender(); return; }
  if(CALC.pick){ CALC.pick = null; calcRender(); }
