  if(cmd.startsWith('i:')){ const [, txt, back] = cmd.match(/^i:(.*?)(?::(\d))?$/); if(CALC.tab!=='calc' && CALC.phase==='out') return;
    if(CALC.tab==='calc' && CALC.fresh && el && /^[+×÷^!%\/]|^−$/.test(txt) && txt!=='−'.repeat(2)){ el.value = 'Ans'; }   // bấm phép toán ngay sau kết quả: tính tiếp trên Ans
    else if(CALC.tab==='calc' && CALC.fresh && el){ el.value = ''; }
    CALC.fresh = false; calcIns(txt, +back||0); return; }
  if(cmd==='LEFT' || cmd==='RIGHT'){ if(!el) return; const p = Math.max(0, Math.min(el.value.length, (el.selectionStart||0) + (cmd==='LEFT' ? -1 : 1))); el.focus(); el.setSelectionRange(p,p); CALC.fresh = false; return; }
  if(cmd==='DEL'){ if(!el) return; CALC.fresh = false; const a = el.selectionStart, b = el.selectionEnd; if(a!==b){ el.value = el.value.slice(0,a) + el.value.slice(b); el.setSelectionRange(a,a); } else if(a > 0){ el.value = el.value.slice(0,a-1) + el.value.slice(a); el.setSelectionRange(a-1,a-1); } el.focus(); if(el.oninput) el.oninput(); return; }
