    if(cmd==='EQ'){ const out = document.getElementById('calcOut'); try{ const v = calcParse(el.value); CALC.ans = v; CALC.last = v; CALC.dec = false; CALC.fresh = true; calcOutShow(); }catch(e){ CALC.last = null; out.innerHTML = `<span class="calc-err">${escHtml(e.message)}</span>`; } return; }
