            if(sn.cssH && !/Ink$/.test(id)) c.style.height = sn.cssH;
            if(sn.cssW && !/Ink$/.test(id) && parseFloat(sn.cssW) > (c.clientWidth||0)) c.style.width = sn.cssW;
            const kc = document.createElement('canvas'); kc.width = img.width; kc.height = img.height; kc.getContext('2d').drawImage(img,0,0);
            c._keep = kc; boardTouch(c);
            if(sn.snapPts && sn.snapPts.pts) c._snap = {boxes: sn.snapPts.boxes||[], pts: sn.snapPts.pts||[], segs: sn.snapPts.segs||[], arcs: sn.snapPts.arcs||[]};
            const ctx = c.getContext('2d'); syncCanvasSize(c, ctx);
