  if(O.drag==='sweep' && Math.abs(O.acc) > 0.001){ ctx.globalAlpha = 1; ctx.strokeStyle = st.color; ctx.lineWidth = st.size; if(st.dashed) ctx.setLineDash([st.size*3+4, st.size*2+3]);
    ctx.beginPath(); ctx.arc(C[0], C[1], r, Math.min(O.a0, O.a0 + O.acc), Math.max(O.a0, O.a0 + O.acc)); ctx.stroke(); ctx.setLineDash([]); }
