  // hai càng compa nối từ khớp (luôn ở phía trên) xuống mũi kim (tâm) và đầu bút chì
  const ux = Math.cos(pa), uy = Math.sin(pa); let nx = -uy, ny = ux; if(ny > 0 || (Math.abs(ny) < 1e-9 && nx > 0)){ nx = -nx; ny = -ny; }
  const L = Math.max(72, r*0.62 + 30), hh = Math.sqrt(Math.max(L*L - r*r/4, 900)), H = [(C[0] + P[0])/2 + nx*hh, (C[1] + P[1])/2 + ny*hh];
  const tw = (A, B, d)=>{ const l = Math.hypot(B[0]-A[0], B[1]-A[1]) || 1; return [A[0] + (B[0]-A[0])*d/l, A[1] + (B[1]-A[1])*d/l]; };
  const line = (A, B, w, col)=>{ ctx.strokeStyle = col; ctx.lineWidth = w; ctx.beginPath(); ctx.moveTo(A[0], A[1]); ctx.lineTo(B[0], B[1]); ctx.stroke(); };
  const leg = (A, B)=>{ line(A, B, 8.4, '#2b2f36'); line(A, B, 6, '#a7b1bc'); };
