  line([H[0] + nx*8, H[1] + ny*8], [H[0] + nx*26, H[1] + ny*26], 8, '#2b2f36'); line([H[0] + nx*8, H[1] + ny*8], [H[0] + nx*26, H[1] + ny*26], 5, '#d4a017');   // tay cầm
  ctx.fillStyle = '#d4a017'; ctx.strokeStyle = '#2b2f36'; ctx.lineWidth = 1.6; ctx.beginPath(); ctx.arc(H[0], H[1], 8.5, 0, 2*Math.PI); ctx.fill(); ctx.stroke();   // khớp
